=== drawing_annotations
// The annotation and assembly tour [SPEC 15.5–15.8]: one housing detailed,
// then assembled. Dimensions: `(-)` spans and chains pack into rows outside
// the geometry (source order, innermost free row), values are measured on the
// seated model in pre-scale drawing units, `unit:` sets the view's physical
// unit, `tol:` composes the tolerance (a deviation stack, a fit class),
// `format:` shapes the number alone, `project:` overrides two point anchors'
// aligned reading, a patterned hole's `(o)` counts its copies, and `side:`
// steers a row. Leaders: tips ray-cast onto the drawn outline and land past a
// horizontal elbow — `<-` arrow, `*-` dot (within a face), `>-` the filled
// datum triangle with its letter in the framed box; a `&` fan shares one note
// across independent legs; `(<)` arcs the angle between two edges; `(o)` reads
// a fillet's radius and drives the diametral line through a round feature. The
// `(-)` selector — the |-| subtype — dresses dimensions alone, so they part
// company from the leaders' wires. The assembly: `||` seats parts along a
// shared normal and draws nothing; the bush's `gap: -20` is the one place gap
// goes below zero, and it presses into a counterbore that is *void* — no two
// materials ever occupy one place. Adjacent parts hatch opposite ways and the
// shaft, being solid, is not sectioned at all. The spindle is a child
// |drawing|, one rigid body reached by dot-path from outside; the overall
// length reads as seated, item balloons wire with `-*`, and the parts list is
// an ordinary |table| beside the view — an assembly needs no |assembly| type.
{
  direction: column; gap: 44;
  |steel::sketch| { fill: hatch(45, 5); }
  |bronze::sketch| { fill: hatch(-45, 4); }
  |-| { stroke: --gray-ink; }
  // every wire — the leaders and the balloon fly-outs
  (-) { stroke: --blue-ink; }
  // dimensions only — beats |-|, the more specific type
}

|drawing#face-view| "GUIDE HOUSING" { unit: mm; } [
  |sketch#flange| {
    draw: move(-55, 48) right(110):base fillet(8):r8 up(96):post left(92):crown
          point():c1 line(-18, 24):flank point():c2 close();
  } [
    |oval#boss| { width: 64; height: 64; fill: none; }
    |hole#seat| { width: 32; }
    |oval#bore| { width: 24; height: 24; fill: none; }
    |hole#bolt| { width: 10; translate: -36 -30; pattern: grid(2, 2, 72, 60); }
  ]

  flange:left (-) flange.bolt.1 (-) flange.bolt.2 (-) flange:right {
    side: bottom;
  }
  // 19 · 72 · 19 — a chain, one row
  flange:left (-) flange:right { side: bottom; }
  // 110 — the outer row
  flange.bolt.1 (-) flange.bolt.3 { side: right; }
  // 60 — the bolt pitch, copy to copy (grid copies row-major)
  flange:top (-) flange:bottom { side: right; tol: 0.2 -0.05; }
  // 96, stacked deviations
  flange.seat (-) flange.bolt.1 { project: horizontal; side: top; }
  // 36 — two point anchors would read the aligned 46.86; `project:` says
  // measure it across
  flange:c1 (-) flange:c2
  // 30 — two point anchors read the true aligned span down the chamfer
  flange:flank (<) flange:crown { format: decimal 1; }
  // 126.9° — the corner cut's included angle, to one decimal
  flange:r8 (o)
  // R8 — the fillet knows its radius
  flange.seat:top-right (o) { tol: H7; }
  // ⌀32 H7 — the diametral line through the bush seat
  flange.bolt (o) "THRU" { side: left; }
  // 4× ⌀10 THRU — the copies counted, the label following the value
  flange.bolt.2 & flange.bolt.4 <- "2× CSK 90°" { side: right; }
  // a fan: one note, a ray-cast leg onto each copy
  flange:base >- "A"
  // datum A on the mounting face
  flange:flank *- "Ra 1.6" { side: left; }
  // a dot lands within the face
]

|row| { gap: 40; align: center; } [

  |drawing#unit-view| "GUIDE UNIT — SECTION" { unit: mm; } [
    |steel#housing| {
      draw: move(-60, -48) right(16) down(16) right(44):boss down(16)
            left(20):seat down(4) left(40):bore close():mount;
      revolve: x-axis;
      // one wall of the flanged housing — the bore reads between the pair
    }
    |bronze#bush| {
      draw: move(-12, -16) right(24):od down(6):face left(24) close();
      revolve: x-axis;
      // adjacent parts hatch opposite ways
    }

    |drawing#spindle| [
      // one rigid body: shaft + knob
      |sketch#shaft| {
        draw: move(-60, -10) right(64) right(26):stub down(20)
              left(26):underside left(64) close();
        fill: --bg;
        // a shaft is solid — never sectioned, never hatched
      }
      |steel#knob| { draw: move(-7, -20) right(14) down(40) left(14) close(); }
      knob:left || shaft:right
    ]
    |centerline| { points: -70 0, 62 0; }
    // the bore axis — redrawn over the solid shaft

    bush:left || housing:right { gap: -20; }
    // pressed 20 into the counterbore — and the counterbore is void, so the
    // two materials never overlap
    spindle.shaft:left || housing:right { gap: -50; }
    // the shaft runs the full bore; the outer mate reaches into the child
    // |drawing| by dot-path, and moves it whole

    housing:left (-) spindle.knob:right { side: bottom; }
    // → 114 — the overall length, as seated

    |balloon#b1| "1" { translate: -40 -70; }
    |balloon#b2| "2" { translate: 2 -70; }
    |balloon#b3| "3" { translate: 30 -70; }
    |balloon#b4| "4" { translate: 64 -70; }
    b1 -* housing:boss
    b2 -* bush:face
    b3 -* spindle.shaft:stub
    b4 -* spindle.knob:top

    spindle.knob:top-right <- "KNURLED" { side: right; }
    // an arrow leader onto the knob's rim
    |note#hint| "SHIM TO SUIT ON ASSEMBLY" { translate: -96 -30; }
    hint -> housing:mount
  ]

  |table#bom| { columns: 22, auto, 30; } [
    "#" "Part"    "Qty"
    "1" "Housing" "1"
    "2" "Bush"    "1"
    "3" "Shaft"   "1"
    "4" "Knob"    "1"
  ]
]

=== drawing_gdt
// GD&T — drafting symbols [SPEC 15.9], the alpha.4 cluster. Stage 1: the
// ISO 1302 surface-texture symbol off the shared drafting-glyph registry in
// natural units — glyph height follows the annotation font, line weight the
// statement's stroke, at any view scale. Stage 2: `|feature-control|` frames
// — the characteristic glyph, the zone-prefixed tolerance with its material
// modifier, the datum references, each in a bordered compartment; `|control|`
// rows compose a composite frame (a shared characteristic merges its symbol
// cell); `|datum|` is the framed letter as a node, joining the scope's datum
// alphabet exactly as `>-` does. `datums:` must name declared letters — a
// frame renders semantically valid or errors, never plausible-wrong.
// Stage 3: `||` with an annotation end is a **seat** [SPEC 15.5] — flush on
// the face after mates, `gap:` along the normal, `translate:` the lateral
// nudge; a `|column|` bundle seats as one and the dim rows stand off it.
// Stage 4: a dimension's `[ ]` **carries** annotation nodes — a frame stacks
// at the text seat, under the value, riding the row as a packing obstacle; a
// carried `|datum|` states the measured feature's axis datum.

|drawing#bracket-view| "MOUNTING BRACKET" { unit: mm; } [
  |rect#plate| { width: 100; height: 72; } [
    |hole#pin| { width: 12; translate: -26 0; }
  ]

  plate:left (-) plate:right { side: bottom; }

  // A carried `|datum|` [SPEC 15.9]: the height reads as a feature of size,
  // and the framed letter under its value makes the mid-plane datum C.
  plate:top (-) plate:bottom { side: right; } [
    |datum| "C"
  ]

  // A carried frame: the bore's size and its location tolerance read as one
  // statement — the ⌀ position zone at maximum material stacks under the
  // value, rides the leader's text seat, and packs as an obstacle.
  plate.pin (o) [
    |feature-control| "position" {
      tol: 0.1; zone: diameter; material: maximum; datums: A, B;
    }
  ]

  // Seated: `||` stands the vee's tip flush on the top face — after mates,
  // both axes — and `translate:` slides it along the face. The cast finish
  // shows the plain placement: the tip is the node's datum, set down by hand.
  |surface-finish#milled| "Ra 1.6" { symbol: machined; }
  milled || plate:top
  |surface-finish#cast| "Ra 6.3" { translate: 30 -36; }

  // Leader-wired: the same placed node, reached from the bore's rim.
  |surface-finish#bore| "Ra 0.8" { symbol: prohibited; translate: -20 -52; }
  plate.pin <- bore

  // The datum alphabet, both forms: the `>-` leader plants A on the mounting
  // face; the `|datum|` node names the bore axis B, wired to its feature.
  plate:bottom >- "A"
  |datum#axis| "B" { translate: -26 22; }
  plate.pin <- axis

  // A composite frame, leader-wired to the feature it controls: the pattern
  // located to the datums, then refined feature-to-feature — adjacent rows
  // share the position symbol cell.
  |feature-control#refine| { translate: -46 -56; } [
    |control| "position" { tol: 0.4; zone: diameter; datums: A, B; }
    |control| "position" { tol: 0.1; zone: diameter; datums: A; }
  ]
  plate.pin <- refine

  // A seated bundle [SPEC 15.5]: the `|column|` of finish over frame is
  // sheet content — the vee stands touching the frame's top edge (ISO 1302),
  // the stack seats as one, flush on the right face, and the vertical
  // dimension row packs past its union box.
  |column#stack| { gap: 0; } [
    |surface-finish| "Ra 3.2" { symbol: machined; }
    |feature-control| "flatness" { tol: 0.2; }
  ]
  stack || plate:right
]

=== drawing_section
// Sourced views [SPEC 15.8] on an ISO 5457 A3 sheet: the front view carries the
// A–A cutting plane and a detail ring; `|drawing| { of: a }` authors the section
// and `{ of: c }` re-renders the ringed corner clipped to the circle at its own
// ratio. A full section is a **cut solid**, not a slice: the hatched faces are
// the material the plane cuts, and the edges **beyond** the plane — the far wall
// of the circlip groove, the chamber floor's rim, the bore's exit, the port's
// mouth — are authored at geometry weight behind them (Lini is 2D, so what
// stands behind the cut is drawn, like the cut itself). `mirror:` reflects the
// wall **and its features** [SPEC 15.3]: the coolant drilling lands in both,
// `2×` on its reading, while the bleed vent declines with `mirror: none`.
// A broken-out section at the right port cuts to its tapped bore, where
// `thread:`'s sense flips [SPEC 15.3]: on an **inner** (even-odd hole)
// subpath the run is the drilled minor and the thin line marks the **major**,
// out by 0.5413 × pitch — outside the drawn bore, not in — and the bare
// leader composes `M24×1.5` from the geometry. Adjacent parts hatch opposite
// ways, a `|hole|`'s `thread:` draws the round view's ¾ arc, annotation
// linework halos where it crosses geometry [SPEC 15.7], and the
// `|title-block|`'s ISO 7200 field properties seat themselves in the frame's
// corner.
{
  |steel::sketch| { fill: hatch(45, 5); }
  |bronze::sketch| { fill: hatch(-45, 4); }
}

|page#sheet| { sheet: a3 landscape; gap: 28; align: origin; } [

  |drawing#front| "PUMP BODY" { scale: 1; } [
    |sketch#body| {
      draw: move(-62, 0) up(52) fillet(12) right(124) fillet(12):c1 down(104)
            fillet(12) left(124) fillet(12) up(52) close();
      fill: none;
    } [
      |hole#bolt| {
        width: 8; translate: -46 -36; pattern: grid(2, 2, 92, 72); thread: 1.25;
      }
      // the cover's four tapped holes — the round view's ¾ thread arc
    ]
    |oval#chamber| { width: 64; height: 64; fill: --bg; stroke: --stroke-dark; }
    |oval#seat| { width: 28; height: 28; fill: --bg; stroke: --stroke-dark; }
    |oval#shaft| { width: 20; height: 20; fill: --bg; stroke: --stroke-dark; }
    |hidden#drill| {
      draw: move(-62, -11.19) right(32.02)
            move(-62, 11.19) right(32.02);
    }
    // the left port's tap drill, hidden in the flange — its twin is broken out
    |steel#port| {
      draw: move(62, -22) left(38.76) fillet(3) arc(6.74, 10.81, 32) fillet(3)
            right(32.02):m24 close();
      // the port wall in local section: the chamber arc, the drilled ⌀22.38,
      // the flange face — and a filleted cut boundary between them
      revolve: x-axis;
      // a bore of revolution about the port axis
      thread: m24 1.5;
      // the bore is an inner subpath, so the thread reads internal
    }

    |plane#a| "A" { at: 0; }
    // a vertical plane on the chamber axis, viewing right
    |magnifier#c| "C" { width: 30; translate: 48 -40; }
    // a corner hole, ringed for detail

    body:left (-) body:right { side: bottom; }
    // 124 across the flange
    body:top (-) body:bottom { side: right; }
    // 104
    chamber (o) { side: left; }
    // ⌀64 — the diametral line, its value carried out past the rim
    port:m24 <- "THRU, 2×" { side: right; }
    // → M24×1.5 THRU, 2× — the spec composes from the drilled bore and the
    // pitch, the authored words following it [SPEC 15.3]
    body.bolt <- "4× M8×1.25, 16 DEEP" { side: bottom; }
  ]

  |drawing#sec| { of: a; scale: 1; } [
    |sketch#beyond| {
      draw: move(-22, -35) down(70)
            move(-19, -35) down(70)
            move(12, -32) down(64)
            move(26, -10) down(20)
            move(-6, 0) circle(11.19);
      fill: none;
    }
    // beyond the cutting plane, at geometry weight: the circlip groove's far
    // wall, the chamber floor's rim, the bore's exit, the port's mouth

    |steel#wall| {
      draw: move(-26, -52) right(52) down(38) left(14) up(18) left(31) up(3)
            left(3) down(3) left(4) close();
      // one wall: the flange, the back wall's leg, the circlip groove
      mirror: x-axis;
      // → both walls (the chamber between)
    } [
      |hole#coolant| { width: 6; translate: -8 -42; }
      // a cross-drilled coolant hole, mid-wall — off the axis, so the mirror
      // hands it to both walls: one feature, two copies, '2×' on the reading
      |hole#vent| { width: 4; translate: 16 -42; mirror: none; }
      // a bleed vent drilled in one wall only — it declines the reflection
    ]
    |bronze#bush| {
      draw: move(12, -14) right(14) down(4) left(14) close();
      mirror: x-axis;
    }
    // the shaft bush, pressed in — adjacent parts hatch opposite ways
    |centerline| { points: -34 0, 34 0; }
    // the chamber axis

    wall:left (-) wall:right { side: bottom; }
    // 52 deep
    wall:left (-) wall.coolant { side: top; }
    // → 18 — the extension line breaks where it crosses the hatched
    // wall [SPEC 15.7]
    wall.coolant (o)
    // → 2× ⌀6 — the mirror's copies prefix the count; the leader breaks
    // over the wall's outer edge
  ]

  |drawing#det| { of: c; scale: 3; } [
    body:c1 (o)
    // → R12 — the detail dimensions the re-laid copy by the id it carries
  ]

  |title-block| {
    title: "Pump body"; drawing-number: "LN-PMP-24-001"; revision: "B"; sheet-number: "1/1"; date: "2026-08-30"; author: "AM";
  }
]

=== drawing_turned
// Turned parts [SPEC 15.3]: two revolved half-profiles on one board. The
// edge-line law draws every sharp diameter change to its axis twin (shoulders,
// groove lips, chamfer edges) while tangent fillets draw none; `thread:` adds
// the ISO minor and thread-end lines; `break:` folds a boring middle out of
// the view with the measured length still true across it; interior geometry
// rides a dashed |hidden| child; and a station `⌀` reads the revolved surface
// doubled about the axis.

{
  direction: column; gap: 48;
  // two long parts, stacked down the board
  |hidden| |centerline| { stroke: none; }
  // a bore's axis — the part's own serves
}

// A 300 mm tie bar with chamfered ends: `thread:` composes the M20×1.5 spec
// the bare leader calls out, and `break:` cuts the featureless middle.
|drawing#tiebar-view| "TIE BAR" { scale: 0.75; unit: mm; } [
  |sketch#bar| {
    draw: move(-150, 0) up(10) chamfer(1.5) right(40):m20 point():a right(260)
          chamfer(1.5) down(10);
    revolve: x-axis; thread: m20 1.5; break: -90 90;
  } [
    |hidden#centre| {
      // the ⌀8 centre bore, drilled 14 deep — the origin sits on the end
      // face, in the far piece, so the bore rides the break with it
      translate: 150 0;
      draw: move(0, 4) left(10) line(-4, -4);
      mirror: x-axis;
    }
  ]

  bar:left (-) bar:right { side: bottom; }
  // → 300 mm — true, across the break
  bar:left (-) bar:a { side: top; }
  // → 40 mm — ':a' is a point() station
  bar:m20 (o) { side: left; tol: h6; }
  // → ⌀20 h6 — doubled about the axis
  bar:m20 <- { side: top; }
  // → M20×1.5 — the thread composes its spec
]

// The multi-section barrel — one named profile carries every value: stations
// chain on one row, ⌀ fits stack at the left in source order, datum A sits on
// the land, and the patterned M8 holes take a typed thread callout.
|drawing#barrel-view| "BARREL" { scale: 0.5; } [
  |sketch#body| {
    draw: move(-242.5, 0) up(21) chamfer(1.5) right(38):m42 point():tl
          right(32):land up(1.5):sh1 right(14):port down(6):sh2 fillet(2):r1
          right(10):groove fillet(2) up(6):sh3 right(10):collar up(2.5)
          right(381):tube chamfer(1.5) down(25);
    revolve: x-axis; thread: m42 1.5; break: -40 215;
  } [
    |hole#m8| {
      width: 8; translate: -120 0; pattern: grid(3, 1, 35, 0); thread: 1.25;
    }
  ]

  body:left (-) body:tl { side: bottom; }
  // → 38 — ':tl' is a point() station
  body:sh1 (-) body:sh2 (-) body:sh3 { side: bottom; }
  // → 14 · 10 — a chain seats one row
  body:left (-) body:right { side: bottom; }
  // → 485 — true, across the break
