                Tok::LinkOp(op) | Tok::DimOp(op) => {
                    let t = self.bump();
                    ops.push((op, t.span));
                }
                Tok::BarBar => {
                    let t = self.bump();
                    ops.push(("||".to_string(), t.span));
                }
                _ => break,
            }
            // one-ended forms: 'a (o)' or 'a <- "text"'
