pub fn pattern_copy(ctx: &Ctx, wrapper: usize, k: usize) -> Option<usize> {
    if !ctx.sk.wrappers.contains_key(&wrapper) || k == 0 {
        return None;
    }
    ctx.nodes[wrapper].children.iter().copied().filter(|c| !ctx.sk.chrome.contains_key(c)).nth(k - 1)
}

