                    self.bump();
                    self.bump();
                    let mut params = Vec::new();
                    loop {
                        match self.peek().clone() {
                            Tok::Ident(p) => {
                                self.bump();
                                params.push(p);
                            }
                            Tok::RParen => {}
                            _ => return Err(perr("expected identifier", self.span())),
                        }
