#[derive(Clone, Debug, Default)]
struct DimText {
    main: String,
    // stacked deviations (upper, lower)
    stack: Option<(String, String)>,
    // measured widths
    w_main: f64,
    w_stack: f64,
}

impl DimText {
    fn width(&self) -> f64 {
        match &self.stack {
            Some(_) => self.w_main + 2.0 + self.w_stack,
            None => self.w_main,
        }
    }
    // half extent across the reading direction
    fn half_h(&self) -> f64 {
        match &self.stack {
            Some(_) => (FONT / 2.0).max(1.1 * FONT * TOL_STACK / 2.0 + FONT * TOL_STACK / 2.0),
            None => FONT / 2.0,
        }
    }
}

fn dev(v: f64) -> String {
    let s = fmt_val(v);
    if s == "0" {
        s
    } else if v > 0.0 {
        format!("+{}", s)
    } else {
        s
    }
}

// The value text with its tolerance (`tol:`) and `format:`.
fn dim_text(ctx: &Ctx, f: usize, st: &St, value: f64, prefix: &str) -> Result<DimText, Diag> {
    let mut main = format!("{}{}", prefix, fmt_number(ctx, st, value));
    let mut stack = None;
    if let Some(v) = st.get("tol") {
        if v.groups.len() > 1 {
            return Err(Diag::error("layout", "'tol' takes one value, not a comma list", v.span));
        }
        let terms = &v.groups[0];
        let bad = || Diag::error("layout", "'tol' takes a number, '+upper -lower', or a fit ident", st.span);
        let nums: Vec<f64> = terms.iter().filter_map(|t| crate::style::term_num(&ctx.sheet.env, t)).collect();
        if terms.len() == 1 && nums.len() == 1 {
            main = format!("{}±{}", main, fmt_val(nums[0]));
        } else if terms.len() == 2 && nums.len() == 2 {
            stack = Some((dev(nums[0]), dev(nums[1])));
        } else if terms.len() == 1 {
            match &terms[0] {
                crate::ast::Term::Ident(s, _) => main = format!("{} {}", main, s),
                _ => return Err(bad()),
            }
        } else {
            return Err(bad());
        }
    }
    if let Some(l) = &st.label {
        if prefix.is_empty() {
            main = l.clone();
        } else {
            main = format!("{} {}", main, l);
        }
    }
    let w_main = tw(ctx, f, FONT, &main);
    let w_stack = match &stack {
        Some((a, b)) => tw(ctx, f, FONT * TOL_STACK, a).max(tw(ctx, f, FONT * TOL_STACK, b)),
        None => 0.0,
    };
    Ok(DimText { main, stack, w_main, w_stack })
}

fn fmt_number(ctx: &Ctx, st: &St, v: f64) -> String {
    if let Some(fv) = st.get("format") {
        let terms: Vec<&crate::ast::Term> = fv.groups.iter().flatten().collect();
        if let Some(crate::ast::Term::Ident(k, _)) = terms.first() {
            if k == "decimal" {
                let n = terms.get(1).and_then(|t| crate::style::term_num(&ctx.sheet.env, t)).unwrap_or(2.0) as usize;
                let p = 10f64.powi(n as i32);
                let r = (v.abs() * p + 0.5 + 1e-9).floor() / p;
                let r = if v < 0.0 { -r } else { r };
                return format!("{:.*}", n, r);
            }
        }
    }
    fmt_val(v)
}

// Text items for a dimension text centred at c, reading along r (unit).
fn text_items(t: &DimText, c: P, r: P, rot: f64) -> Vec<Item> {
    let up = pt(r.y, -r.x);
    match &t.stack {
        None => vec![Item::text(c, &t.main, rot, None)],
        Some((a, b)) => {
            let w = t.width();
            let cm = c.sub(r.mul(w / 2.0 - t.w_main / 2.0));
            let cs = c.add(r.mul(w / 2.0 - t.w_stack / 2.0));
            let k = 1.1 * FONT * TOL_STACK / 2.0;
            let sz = Some(FONT * TOL_STACK);
            vec![
                Item::text(cm, &t.main, rot, None),
                Item::text(cs.add(up.mul(k)), a, rot, sz),
                Item::text(cs.sub(up.mul(k)), b, rot, sz),
            ]
        }
    }
}

fn arrow(tip: P, d: P) -> Vec<P> {
    // d: from the tip toward the arrow's base
    let base = tip.add(d.mul(ARROW_L));
    let l = pt(d.y, -d.x);
    vec![tip, base.add(l.mul(ARROW_HW)), base.sub(l.mul(ARROW_HW))]
}

// ------------------------------------------------------------ linear dimensions

#[derive(Clone, Copy, Debug, PartialEq)]
enum Axis {
    X,
    Y,
    // aligned: the unit direction a → b
    A(P),
}

#[derive(Clone, Debug, Default)]
struct Row {
    // dim line position along the outward coordinate
    l: f64,
    far: f64,
    spans: Vec<(f64, f64)>,
}

#[derive(Default)]
struct Layout {
    geo: BBox,
    // leader notes etc. that dimension rows clear
    obstacles: Vec<BBox>,
    rows: HashMap<&'static str, Vec<Row>>,
    // arrow tips landing on geometry
    tips: Vec<P>,
}

fn outward(side: &str) -> P {
    side_dir(side).unwrap_or(pt(0.0, 1.0))
}

fn side_static(s: &str) -> &'static str {
    match s {
        "top" => "top",
        "left" => "left",
        "right" => "right",
        _ => "bottom",
    }
}

// The outermost extent of the geometry (and notes) along a side's outward axis.
fn extent(lay: &Layout, side: &str) -> f64 {
    let mut boxes = vec![lay.geo];
    boxes.extend(lay.obstacles.iter().copied());
    let mut e = f64::NEG_INFINITY;
    for b in boxes {
        if b.is_empty() {
            continue;
        }
        let v = match side {
            "top" => -b.y0,
            "left" => -b.x0,
            "right" => b.x1,
            _ => b.y1,
        };
        e = e.max(v);
    }
    if e == f64::NEG_INFINITY {
        0.0
    } else {
        e
    }
}

fn dim_axis(a: &Ref, b: &Ref, project: Option<&str>) -> Result<Axis, String> {
    match project {
        Some("horizontal") => return Ok(Axis::X),
        Some("vertical") => return Ok(Axis::Y),
        _ => {}
    }
    let pick = |n: P| if n.x.abs() > n.y.abs() { Axis::X } else { Axis::Y };
    match (a.n, b.n) {
        (Some(na), Some(nb)) => {
            if na.cross(nb).abs() < 1e-6 {
                Ok(pick(na))
            } else {
                Err("perp".into())
            }
        }
        (Some(na), None) => Ok(pick(na)),
        (None, Some(nb)) => Ok(pick(nb)),
        (None, None) => {
            let d = b.p.sub(a.p);
            if d.x.abs() < 1e-6 {
                Ok(Axis::Y)
            } else if d.y.abs() < 1e-6 {
                Ok(Axis::X)
            } else {
                Ok(Axis::A(d.unit()))
            }
        }
    }
}

fn along(ax: Axis, p: P) -> f64 {
    match ax {
        Axis::X => p.x,
        Axis::Y => p.y,
        Axis::A(d) => p.dot(d),
    }
}

struct Lin {
    a: Ref,
    b: Ref,
    li: usize,
}

fn lay_linear(ctx: &Ctx, f: usize, st: &St, lins: &[Lin], lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
    if lins.is_empty() {
        return Ok(());
    }
    let project = st.ident("project");
    let ax = match dim_axis(&lins[0].a, &lins[0].b, project.as_deref()) {
        Ok(a) => a,
        Err(_) => {
            let l = &ctx.links[lins[0].li];
            let name = |n: usize, a: &Option<String>| {
                let p = crate::links::path_of(ctx, n);
                match a {
                    Some(a) => format!("{}:{}", p, a),
                    None => p,
                }
            };
            let msg = format!(
                "'{} (-) {}' — perpendicular faces have no shared normal; the angle between edges is '(<)'",
                name(l.from, &l.from_anchor),
                name(l.to, &l.to_anchor)
            );
            return Err(Diag::error("layout", &msg, st.span));
        }
    };
    let k = crate::drawing::ps(ctx, f);
    if let Axis::A(_) = ax {
        for lin in lins {
            lay_aligned(ctx, f, st, lin, k, lay, out)?;
        }
        return Ok(());
    }
    let side: &'static str = match st.ident("side") {
        Some(s) => side_static(&s),
        None => {
            if ax == Axis::X {
                "bottom"
            } else {
                "right"
            }
        }
    };
    let o = outward(side);
    // texts first: the row band depends on them
    let mut texts = Vec::new();
    let mut lo = f64::INFINITY;
    let mut hi = f64::NEG_INFINITY;
    for lin in lins {
        let (pa, pb) = (along(ax, lin.a.p), along(ax, lin.b.p));
        let t = dim_text(ctx, f, st, (pb - pa).abs() / k, "")?;
        lo = lo.min(pa.min(pb));
        hi = hi.max(pa.max(pb));
        texts.push(t);
    }
    // the band around the dim line, along the outward coordinate s
    let hh = texts.iter().map(|t| t.half_h()).fold(FONT / 2.0, f64::max);
    let inner_text = matches!(side, "bottom" | "right");
    let (near_off, far_off) = if inner_text { (-(TEXT_OFF + hh), EXT_OVER) } else { (-ARROW_HW, TEXT_OFF + hh) };
    let base = extent(lay, side);
    let rows = lay.rows.entry(side).or_default();
    let mut row_ix = None;
    for (ri, r) in rows.iter().enumerate() {
        if r.spans.iter().all(|&(a, b)| !(lo < b - 1e-6 && a < hi - 1e-6)) {
            row_ix = Some(ri);
            break;
        }
    }
    let ri = match row_ix {
        Some(ri) => ri,
        None => {
            let near = match rows.last() {
                Some(r) => r.far,
                None => base,
            } + CLEAR;
            let l = near - near_off;
            rows.push(Row { l, far: l + far_off, spans: vec![] });
            rows.len() - 1
        }
    };
    rows[ri].spans.push((lo, hi));
    let ls = rows[ri].l;
    rows[ri].far = rows[ri].far.max(ls + far_off);
    // the dim line's position in frame coordinates
    let lpos = match side {
        "top" | "left" => -ls,
        _ => ls,
    };
    for (lin, t) in lins.iter().zip(texts.iter()) {
        let on_line = |p: P| -> P {
            match ax {
                Axis::X => pt(p.x, lpos),
                _ => pt(lpos, p.y),
            }
        };
        let (a, b) = (&lin.a, &lin.b);
        // extension lines
        for r in [a, b] {
            let q = on_line(r.p);
            let s = r.p.add(o.mul(EXT_GAP));
            let e = q.add(o.mul(EXT_OVER));
            let mut it = Item::new(Kind::Line, "lini-ext-line", vec![s, e]);
            it.halo = true;
            out.push(it);
        }
        let (qa, qb) = (on_line(a.p), on_line(b.p));
        let axis_u = if ax == Axis::X { pt(1.0, 0.0) } else { pt(0.0, 1.0) };
        let span = qb.sub(qa).len();
        let u = if span > 1e-9 { qb.sub(qa).unit() } else { axis_u };
        let tw_all = t.width();
        let inside = span >= tw_all + 30.0;
        let (l0, l1) = if inside { (qa.add(u.mul(LINE_INSET)), qb.sub(u.mul(LINE_INSET))) } else { (qa.sub(u.mul(ARROW_L + LINE_INSET)), qb.add(u.mul(ARROW_L + LINE_INSET))) };
        let mut dl = Item::new(Kind::Line, "lini-dim-line", vec![l0, l1]);
        dl.halo = true;
        out.push(dl);
        let (da, db) = if inside { (u, u.mul(-1.0)) } else { (u.mul(-1.0), u) };
        let mut m1 = Item::new(Kind::Polygon, "lini-marker lini-marker-dim", arrow(qa, da));
        m1.tip = Some(qa);
        out.push(m1);
        let mut m2 = Item::new(Kind::Polygon, "lini-marker lini-marker-dim", arrow(qb, db));
        m2.tip = Some(qb);
        out.push(m2);
        // the text: reading left to right / bottom to top
        let (r, rot) = if ax == Axis::X { (pt(1.0, 0.0), 0.0) } else { (pt(0.0, -1.0), -90.0) };
        let up = pt(r.y, -r.x);
        let text_inside = span >= tw_all + 4.0;
        let mid = qa.add(qb).mul(0.5);
        let c = if text_inside {
            mid
        } else {
            let end = qb.add(u.mul(ARROW_L + LINE_INSET + 4.0));
            end.add(u.mul(tw_all / 2.0))
        };
        out.extend(text_items(t, c.add(up.mul(TEXT_OFF)), r, rot));
    }
    Ok(())
}

// A dimension along two point anchors' own line: offset to the anchor
// line's left, clear of the anchors alone.
fn lay_aligned(ctx: &Ctx, f: usize, st: &St, lin: &Lin, k: f64, _lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
    let (a, b) = (&lin.a, &lin.b);
    let d = b.p.sub(a.p).unit();
    let o = pt(d.y, -d.x);
    let off = CLEAR + ARROW_HW;
    let t = dim_text(ctx, f, st, b.p.sub(a.p).len() / k, "")?;
    for r in [a, b] {
        let mut it = Item::new(Kind::Line, "lini-ext-line", vec![r.p.add(o.mul(EXT_GAP)), r.p.add(o.mul(off + EXT_OVER))]);
        it.halo = true;
        out.push(it);
    }
    let (qa, qb) = (a.p.add(o.mul(off)), b.p.add(o.mul(off)));
    let span = qb.sub(qa).len();
    let u = d;
    let inside = span >= t.width() + 30.0;
    let (l0, l1) = if inside { (qa.add(u.mul(LINE_INSET)), qb.sub(u.mul(LINE_INSET))) } else { (qa.sub(u.mul(ARROW_L + LINE_INSET)), qb.add(u.mul(ARROW_L + LINE_INSET))) };
    let mut dl = Item::new(Kind::Line, "lini-dim-line", vec![l0, l1]);
    dl.halo = true;
    out.push(dl);
    let (da, db) = if inside { (u, u.mul(-1.0)) } else { (u.mul(-1.0), u) };
    let mut m1 = Item::new(Kind::Polygon, "lini-marker lini-marker-dim", arrow(qa, da));
    m1.tip = Some(qa);
    out.push(m1);
    let mut m2 = Item::new(Kind::Polygon, "lini-marker lini-marker-dim", arrow(qb, db));
    m2.tip = Some(qb);
    out.push(m2);
    // keep the text upright
    let mut r = d;
    if r.x < -1e-9 || (r.x.abs() <= 1e-9 && r.y > 0.0) {
        r = r.mul(-1.0);
    }
    let rot = r.y.atan2(r.x).to_degrees();
    let up = pt(r.y, -r.x);
    let mid = qa.add(qb).mul(0.5);
    out.extend(text_items(&t, mid.add(up.mul(TEXT_OFF)), r, rot));
    Ok(())
}

input.old_string:
    let rot = r.y.atan2(r.x).to_degrees();
    let up = pt(r.y, -r.x);
    let mid = qa.add(qb).mul(0.5);
    out.extend(text_items(&t, mid.add(up.mul(TEXT_OFF)), r, rot));
    Ok(())
}

input.new_string:
    let rot = r.y.atan2(r.x).to_degrees();
    let up = pt(r.y, -r.x);
    let mid = qa.add(qb).mul(0.5);
    out.extend(text_items(&t, mid.add(up.mul(TEXT_OFF)), r, rot));
    Ok(())
}

// ------------------------------------------------------------ leaders

// Gap between two boxes (negative when they overlap on both axes).
fn box_gap(a: &BBox, b: &BBox) -> f64 {
    let gx = (a.x0 - b.x1).max(b.x0 - a.x1);
    let gy = (a.y0 - b.y1).max(b.y0 - a.y1);
    gx.max(gy)
}

// How far the ray from p (inside or on the box) runs before leaving it.
fn exit_t(b: &BBox, p: P, u: P) -> f64 {
    let mut t = f64::INFINITY;
    if u.x > 1e-12 {
        t = t.min((b.x1 - p.x) / u.x);
    } else if u.x < -1e-12 {
        t = t.min((b.x0 - p.x) / u.x);
    }
    if u.y > 1e-12 {
        t = t.min((b.y1 - p.y) / u.y);
    } else if u.y < -1e-12 {
        t = t.min((b.y0 - p.y) / u.y);
    }
    if t.is_finite() {
        t.max(0.0)
    } else {
        0.0
    }
}

// A note's box: the landing runs from the knee along h, the text after a gap.
fn note_box(knee: P, h: f64, w: f64, hh: f64) -> BBox {
    let x0 = knee.x + h * (NOTE_LANDING + NOTE_GAP);
    let x1 = x0 + h * w;
    let mut b = BBox::empty();
    b.add(x0.min(x1), knee.y - hh);
    b.add(x0.max(x1), knee.y + hh);
    b
}

// The knee on the ray tip + t·u: out of the geometry box by NOTE_OFFSET, then
// further until the note (width w, half height hh) clears it by NOTE_OFFSET.
fn knee_on(geo: &BBox, tip: P, u: P, w: f64, hh: f64) -> (P, f64) {
    let t0 = exit_t(geo, tip, u) + NOTE_OFFSET;
    let h = if u.x < -1e-9 { -1.0 } else { 1.0 };
    let at = |t: f64| tip.add(u.mul(t));
    if box_gap(&note_box(at(t0), h, w, hh), geo) >= NOTE_OFFSET - 1e-9 {
        return (at(t0), h);
    }
    let mut best = f64::INFINITY;
    let lead = NOTE_LANDING + NOTE_GAP;
    if u.x > 1e-9 {
        best = best.min((geo.x1 + NOTE_OFFSET - lead - tip.x) / u.x);
    } else if u.x < -1e-9 {
        best = best.min((geo.x0 - NOTE_OFFSET + lead - tip.x) / u.x);
    }
    if u.y > 1e-9 {
        best = best.min((geo.y1 + NOTE_OFFSET + hh - tip.y) / u.y);
    } else if u.y < -1e-9 {
        best = best.min((geo.y0 - NOTE_OFFSET - hh - tip.y) / u.y);
    }
    if !best.is_finite() || best < t0 {
        best = t0;
    }
    (at(best), h)
}

// Where a leader's ray meets a node's outline from its centre.
fn rim(ctx: &Ctx, f: usize, i: usize, u: P) -> Option<P> {
    let n = &ctx.nodes[i];
    let m = to_frame(ctx, i, f);
    let c = apply(&m, pt(-n.geo_off.0, -n.geo_off.1));
    match n.prim {
        Prim::Oval => {
            // the ellipse in the node frame (axis-aligned there)
            let inv = invert(&m)?;
            let lu = apply_v(&inv, u);
            let (rx, ry) = (n.w / 2.0, n.h / 2.0);
            if rx <= 0.0 || ry <= 0.0 {
                return Some(c);
            }
            let k = 1.0 / ((lu.x / rx).powi(2) + (lu.y / ry).powi(2)).sqrt();
            Some(c.add(u.mul(k * lu.len() / lu.len().max(1e-12))))
        }
        _ => {
            let (hw, hh) = (n.w / 2.0, n.h / 2.0);
            let inv = invert(&m)?;
            let lu = apply_v(&inv, u);
            let mut t = f64::INFINITY;
            if lu.x.abs() > 1e-12 {
                t = t.min(hw / lu.x.abs());
            }
            if lu.y.abs() > 1e-12 {
                t = t.min(hh / lu.y.abs());
            }
            if !t.is_finite() {
                return Some(c);
            }
            Some(c.add(u.mul(t)))
        }
    }
}

fn invert(m: &M) -> Option<M> {
    let det = m[0] * m[3] - m[1] * m[2];
    if det.abs() < 1e-12 {
        return None;
    }
    let a = m[3] / det;
    let b = -m[1] / det;
    let c = -m[2] / det;
    let d = m[0] / det;
    let e = -(a * m[4] + c * m[5]);
    let f = -(b * m[4] + d * m[5]);
    Some([a, b, c, d, e, f])
}

// The ray a leader follows from its feature: `side:` turns it to that
// side's normal; otherwise out from the frame datum through the feature.
fn leader_dir(st: &St, through: P) -> P {
    if let Some(s) = st.ident("side") {
        if let Some(d) = side_dir(&s) {
            return d;
        }
    }
    if through.len() < 1e-9 {
        return pt(1.0, -1.0).unit();
    }
    through.unit()
}

// The composed thread spec of a sketch ("M8×1.25"), if it has one.
fn thread_spec(ctx: &Ctx, i: usize) -> Option<String> {
    let v = ctx.nodes[i].props.get("thread")?;
    let terms: Vec<&crate::ast::Term> = v.groups.iter().flatten().collect();
    let mut name = None;
    let mut pitch = None;
    for t in terms {
        match t {
            crate::ast::Term::Ident(s, _) => name = Some(s.clone()),
            _ => {
                if let Some(x) = crate::style::term_num(&ctx.sheet.env, t) {
                    pitch = Some(x);
                }
            }
        }
    }
    let name = name?;
    let up = name.to_uppercase();
    match pitch {
        Some(p) => Some(format!("{}×{}", up, fmt_val(p))),
        None => Some(up),
    }
}

fn label_text(st: &St, base: Option<String>) -> String {
    match (base, &st.label) {
        (Some(b), Some(l)) => format!("{} {}", b, l),
        (Some(b), None) => b,
        (None, Some(l)) => l.clone(),
        (None, None) => String::new(),
    }
}

// A leader note: tip on the feature, a ray out to the knee, the landing and
// the text. `marker`: "arrow" | "dot" | "datum".
fn lay_note(ctx: &Ctx, f: usize, st: &St, r: &Ref, text: &str, lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
    let u = match (r.n, st.ident("side")) {
        (Some(n), None) => n,
        _ => leader_dir(st, r.p),
    };
    let tip = if r.feature { rim(ctx, f, r.node, u).unwrap_or(r.p) } else { r.p };
    let w = tw(ctx, f, FONT, text);
    let (knee, h) = knee_on(&lay.geo, tip, u, w, FONT / 2.0);
    let land = knee.add(pt(h * NOTE_LANDING, 0.0));
    let mut line = Item::new(Kind::Polyline, "lini-dim-line", vec![tip.add(u.mul(LINE_INSET)), knee, land]);
    line.halo = true;
    out.push(line);
    let mut m = Item::new(Kind::Polygon, "lini-marker lini-marker-dim", arrow(tip, u));
    m.tip = Some(tip);
    out.push(m);
    lay.tips.push(tip);
    let c = pt(knee.x + h * (NOTE_LANDING + NOTE_GAP + w / 2.0), knee.y);
    out.push(Item::text(c, text, 0.0, None));
    lay.obstacles.push(note_box(knee, h, w, FONT / 2.0));
    Ok(())
}

// A datum: the filled triangle on the face, a leader out to the framed letter.
fn lay_datum(ctx: &Ctx, f: usize, st: &St, r: &Ref, letter: &str, lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
    let _ = ctx;
    let _ = f;
    let u = match (r.n, st.ident("side")) {
        (Some(n), None) => n,
        _ => leader_dir(st, r.p),
    };
    let base = r.p;
    let apex = base.add(u.mul(DATUM_TRI));
    let l = pt(u.y, -u.x);
    let box_s = 18.0;
    let (knee, h) = knee_on(&lay.geo, apex, u, box_s - NOTE_GAP, box_s / 2.0);
    // the frame box sits right after the landing (no text gap)
    let land = knee.add(pt(h * NOTE_LANDING, 0.0));
    let mut line = Item::new(Kind::Polyline, "lini-dim-line", vec![apex, knee, land]);
    line.halo = true;
    out.push(line);
    let tri = vec![base.add(l.mul(DATUM_TRI / 2.0)), base.sub(l.mul(DATUM_TRI / 2.0)), apex];
    out.push(Item::new(Kind::Polygon, "lini-marker lini-marker-datum", tri));
    let x0 = land.x;
    let x1 = land.x + h * box_s;
    let c = pt((x0 + x1) / 2.0, knee.y);
    out.push(Item::text(c, letter, 0.0, None));
    let (bx0, bx1) = (x0.min(x1), x0.max(x1));
    let (by0, by1) = (knee.y - box_s / 2.0, knee.y + box_s / 2.0);
    let frame = if h > 0.0 {
        vec![pt(bx0, by0), pt(bx1, by0), pt(bx1, by1), pt(bx0, by1), pt(bx0, by0)]
    } else {
        vec![pt(bx1, by0), pt(bx0, by0), pt(bx0, by1), pt(bx1, by1), pt(bx1, by0)]
    };
    out.push(Item::new(Kind::Polyline, "lini-dim-line lini-datum-frame", frame));
    let mut b = BBox::empty();
    b.add(bx0, by0);
    b.add(bx1, by1);
    lay.obstacles.push(b);
    Ok(())
}

// A diameter / radius: through a round feature, at a fillet, or a station ⌀
// on a revolved run.
fn lay_round(ctx: &Ctx, f: usize, st: &St, r: &Ref, lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
    let k = crate::drawing::ps(ctx, f);
    if let Some((c, rad)) = r.arc {
        // a radius: the arrow on the arc, the leader out
        let t = dim_text(ctx, f, st, rad / k, "R")?;
        let txt = t.main.clone();
        let u = leader_dir(st, r.p);
        let tip = r.p;
        let _ = c;
        let w = tw(ctx, f, FONT, &txt);
        let (knee, h) = knee_on(&lay.geo, tip, u, w, FONT / 2.0);
        let land = knee.add(pt(h * NOTE_LANDING, 0.0));
        let mut line = Item::new(Kind::Polyline, "lini-dim-line", vec![tip.add(u.mul(LINE_INSET)), knee, land]);
        line.halo = true;
        out.push(line);
        let mut m = Item::new(Kind::Polygon, "lini-marker lini-marker-dim", arrow(tip, u));
        m.tip = Some(tip);
        out.push(m);
        lay.tips.push(tip);
        let cpos = pt(knee.x + h * (NOTE_LANDING + NOTE_GAP + w / 2.0), knee.y);
        out.push(Item::text(cpos, &txt, 0.0, None));
        lay.obstacles.push(note_box(knee, h, w, FONT / 2.0));
        return Ok(());
    }
    if r.feature {
        let n = &ctx.nodes[r.node];
        let d = n.w;
        let prefix = if r.copies > 1 { format!("{}× ⌀", r.copies) } else { "⌀".to_string() };
        let t = dim_text(ctx, f, st, d / k, &prefix)?;
        let txt = t.main.clone();
        let u = leader_dir(st, r.p);
        let near = rim(ctx, f, r.node, u).unwrap_or(r.p);
        let far = rim(ctx, f, r.node, u.mul(-1.0)).unwrap_or(r.p);
        let w = tw(ctx, f, FONT, &txt);
        let (knee, h) = knee_on(&lay.geo, near, u, w, FONT / 2.0);
        let land = knee.add(pt(h * NOTE_LANDING, 0.0));
        let start = far.sub(u.mul(ARROW_L + LINE_INSET));
        let mut line = Item::new(Kind::Polyline, "lini-dim-line", vec![start, knee, land]);
        line.halo = true;
        out.push(line);
        let mut m1 = Item::new(Kind::Polygon, "lini-marker lini-marker-dim", arrow(near, u));
        m1.tip = Some(near);
        out.push(m1);
        let mut m2 = Item::new(Kind::Polygon, "lini-marker lini-marker-dim", arrow(far, u.mul(-1.0)));
        m2.tip = Some(far);
        out.push(m2);
        lay.tips.push(near);
        lay.tips.push(far);
        let cpos = pt(knee.x + h * (NOTE_LANDING + NOTE_GAP + w / 2.0), knee.y);
        out.push(Item::text(cpos, &txt, 0.0, None));
        lay.obstacles.push(note_box(knee, h, w, FONT / 2.0));
        return Ok(());
    }
    Ok(())
}

