// ------------------------------------------------------------ frame layout

fn first_error(ctx: &mut Ctx, e: Diag) {
    if ctx.an.error.is_none() {
        ctx.an.error = Some(e);
    }
}

fn ref_of(ctx: &Ctx, f: usize, li: usize, to: bool) -> Result<Ref, Diag> {
    let l = &ctx.links[li];
    let (n, a, ix) = if to { (l.to, &l.to_anchor, l.to_index) } else { (l.from, &l.from_anchor, l.from_index) };
    resolve(ctx, f, n, a.as_deref(), ix).map_err(|m| Diag::error("layout", &m, l.span))
}

// Lay out every annotation written in drawing frame f; `bb` (the parts'
// content box, datum frame) grows to hold them.
pub fn layout(ctx: &mut Ctx, f: usize, bb: &mut BBox) {
    let sts = statements(ctx, f);
    if sts.is_empty() {
        return;
    }
    let mut lay = Layout { geo: *bb, ..Default::default() };
    let mut per: Vec<Vec<Item>> = vec![vec![]; sts.len()];
    let mut errs: Vec<Diag> = Vec::new();
    // pass 1: leaders, round features, datums — they stand off the geometry
    for (k, st) in sts.iter().enumerate() {
        let r = match st.op.as_str() {
            "<-" | "*-" | ">-" => lay_leader_stmt(ctx, f, st, &mut lay, &mut per[k]),
            "(o)" => lay_round_stmt(ctx, f, st, &mut lay, &mut per[k], false),
            _ => Ok(()),
        };
        if let Err(e) = r {
            errs.push(e);
        }
    }
    // pass 2: linear dimensions (and station diameters) pack into rows
    for (k, st) in sts.iter().enumerate() {
        let r = match st.op.as_str() {
            "(-)" => {
                let mut lins = Vec::new();
                let mut bad = None;
                for &li in &st.links {
                    match (ref_of(ctx, f, li, false), ref_of(ctx, f, li, true)) {
                        (Ok(a), Ok(b)) => lins.push(Lin { a, b, li }),
                        (Err(e), _) | (_, Err(e)) => {
                            bad = Some(e);
                            break;
                        }
                    }
                }
                match bad {
                    Some(e) => Err(e),
                    None => lay_linear(ctx, f, st, &lins, &mut lay, &mut per[k]),
                }
            }
            "(o)" => lay_round_stmt(ctx, f, st, &mut lay, &mut per[k], true),
            _ => Ok(()),
        };
        if let Err(e) = r {
            errs.push(e);
        }
    }
    for e in errs {
        first_error(ctx, e);
    }
    let mut items: Vec<Item> = per.into_iter().flatten().collect();
    halos(ctx, f, &lay, &mut items);
    // the frame grows to hold the annotations
    let mut ab = BBox::empty();
    for it in &items {
        item_bbox(ctx, f, it, &mut ab);
    }
    if !ab.is_empty() {
        bb.add(ab.x0, ab.y0);
        bb.add(ab.x1, ab.y1);
    }
    ctx.an.frames.insert(f, Frame { shift: pt(0.0, 0.0), items, bbox: ab });
}

// The frame's centring shift (applied to its children after layout).
pub fn set_shift(ctx: &mut Ctx, f: usize, dx: f64, dy: f64) {
    if let Some(fr) = ctx.an.frames.get_mut(&f) {
        fr.shift = pt(dx, dy);
    }
}

fn item_bbox(ctx: &Ctx, f: usize, it: &Item, b: &mut BBox) {
    match it.kind {
        Kind::Text => {
            let size = it.size.unwrap_or(FONT);
            let w = tw(ctx, f, size, &it.text);
            let c = it.pts[0];
            let (hx, hy) = if (it.rot.abs() - 90.0).abs() < 1e-9 { (size / 2.0, w / 2.0) } else { (w / 2.0, size / 2.0) };
            if it.rot != 0.0 && (it.rot.abs() - 90.0).abs() >= 1e-9 {
                let a = it.rot.to_radians();
                let (s, co) = a.sin_cos();
                for (x, y) in [(-w / 2.0, -size / 2.0), (w / 2.0, -size / 2.0), (w / 2.0, size / 2.0), (-w / 2.0, size / 2.0)] {
                    b.add(c.x + x * co - y * s, c.y + x * s + y * co);
                }
            } else {
                b.add(c.x - hx, c.y - hy);
                b.add(c.x + hx, c.y + hy);
            }
        }
        Kind::Node(_) => {}
        _ => {
            for p in &it.pts {
                b.add(p.x, p.y);
            }
        }
    }
}

fn lay_leader_stmt(ctx: &Ctx, f: usize, st: &St, lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
    for &li in &st.links {
        let r = ref_of(ctx, f, li, false)?;
        match st.op.as_str() {
            ">-" => {
                let letter = st.label.clone().unwrap_or_default();
                lay_datum(ctx, f, st, &r, &letter, lay, out)?;
            }
            _ => {
                let base = if r.feature || r.run.is_some() { thread_of(ctx, &r) } else { None };
                let text = label_text(st, base);
                lay_note(ctx, f, st, &r, &text, lay, out)?;
            }
        }
    }
    Ok(())
}

// The thread a leader's feature carries ("M8×1.25").
fn thread_of(ctx: &Ctx, r: &Ref) -> Option<String> {
    if ctx.nodes[r.node].prim == Prim::Sketch {
        return thread_spec(ctx, r.node);
    }
    None
}

fn lay_round_stmt(ctx: &Ctx, f: usize, st: &St, lay: &mut Layout, out: &mut Vec<Item>, rows: bool) -> Result<(), Diag> {
    for &li in &st.links {
        let r = ref_of(ctx, f, li, false)?;
        let station = r.run.is_some() && r.twin.is_some();
        if station != rows {
            continue;
        }
        if station {
            // a ⌀ station on a revolved run: the run and its twin, measured across
            let (a0, a1) = r.run.unwrap();
            let (b0, b1) = r.twin.unwrap();
            let pa = a0.add(a1).mul(0.5);
            let pb = b0.add(b1).mul(0.5);
            let ra = Ref { run: None, n: None, twin: None, p: pa, ..r.clone() };
            let rb = Ref { run: None, n: None, twin: None, p: pb, ..r.clone() };
            lay_station(ctx, f, st, ra, rb, li, lay, out)?;
        } else {
            lay_round(ctx, f, st, &r, lay, out)?;
        }
    }
    Ok(())
}

// A diameter read across a revolved run and its twin: a dimension row.
fn lay_station(ctx: &Ctx, f: usize, st: &St, a: Ref, b: Ref, li: usize, lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
    let st2 = St { label: None, ..st.clone() };
    let mut tmp = Vec::new();
    // measure as a linear dimension with the ⌀ prefix
    let lins = vec![Lin { a, b, li }];
    lay_linear_pref(ctx, f, &st2, &lins, lay, &mut tmp, "⌀")?;
    out.extend(tmp);
    Ok(())
}

// ------------------------------------------------------------ halos

#[derive(Clone, Debug)]
enum Outline {
    Seg(Seg, f64),
    Ellipse(M, f64, f64, f64),
}

fn outlines(ctx: &Ctx, f: usize) -> Vec<Outline> {
    let mut out = Vec::new();
    let mut stack: Vec<usize> = ctx.nodes[f].children.iter().rev().copied().collect();
    while let Some(i) = stack.pop() {
        let n = &ctx.nodes[i];
        if n.prim == Prim::Text || crate::drawing::is_chrome(ctx, i) || ctx.sk.chrome.contains_key(&i) {
            continue;
        }
        if crate::drawing::is_frame(ctx, i) && !crate::drawing::in_drawing(ctx, i) {
            continue;
        }
        let m = to_frame(ctx, i, f);
        let sw = if ctx.sk.copies.contains(&i) { 0.0 } else { stroke_w(ctx, i) };
        if !is_wrapper(ctx, i) && ctx.comp[i].has_stroke {
            let c = pt(-n.geo_off.0, -n.geo_off.1);
            let (hw, hh) = (n.w / 2.0, n.h / 2.0);
            match n.prim {
                Prim::Oval => {
                    let mm = mul(&m, &[1.0, 0.0, 0.0, 1.0, c.x, c.y]);
                    out.push(Outline::Ellipse(mm, hw, hh, sw));
                }
                Prim::Sketch => {
                    if let Some(l) = ctx.sk.laid.get(&i) {
                        for s in &l.shape.subs {
                            for g in &s.segs {
                                out.push(Outline::Seg(map_seg(&m, g), sw));
                            }
                            if s.closed && !s.end().near(s.start) {
                                out.push(Outline::Seg(map_seg(&m, &Seg::Line { a: s.end(), b: s.start }), sw));
                            }
                        }
                    }
                }
                Prim::Block if n.w > 0.0 && n.h > 0.0 => {
                    let cs = [pt(c.x - hw, c.y - hh), pt(c.x + hw, c.y - hh), pt(c.x + hw, c.y + hh), pt(c.x - hw, c.y + hh)];
                    for k in 0..4 {
                        out.push(Outline::Seg(Seg::Line { a: apply(&m, cs[k]), b: apply(&m, cs[(k + 1) % 4]) }, sw));
                    }
                }
                Prim::Hex if n.w > 0.0 && n.h > 0.0 => {
                    let ps = [pt(-hw, 0.0), pt(-hw / 2.0, -hh), pt(hw / 2.0, -hh), pt(hw, 0.0), pt(hw / 2.0, hh), pt(-hw / 2.0, hh)];
                    for k in 0..6 {
                        out.push(Outline::Seg(Seg::Line { a: apply(&m, ps[k].add(c)), b: apply(&m, ps[(k + 1) % 6].add(c)) }, sw));
                    }
                }
                _ => {}
            }
        }
        if crate::drawing::is_frame(ctx, i) {
            // a nested drawing's parts count too
        }
        for &ch in n.children.iter().rev() {
            stack.push(ch);
        }
    }
    out
}

// Crossings of segment p→q with an outline: (t along p→q, sin of the angle).
fn crossings(p: P, q: P, o: &Outline) -> Vec<(f64, f64)> {
    let d = q.sub(p);
    let len = d.len();
    if len < 1e-12 {
        return vec![];
    }
    let u = d.mul(1.0 / len);
    let mut out = Vec::new();
    match o {
        Outline::Seg(Seg::Line { a, b }, _) => {
            let e = b.sub(*a);
            let den = d.cross(e);
            if den.abs() < 1e-12 {
                return out;
            }
            let w = a.sub(p);
            let t = w.cross(e) / den;
            let s = w.cross(d) / den;
            if t > 1e-9 && t < 1.0 - 1e-9 && s >= -1e-9 && s <= 1.0 + 1e-9 {
                let sin = (u.cross(e.unit())).abs();
                out.push((t, sin));
            }
        }
        Outline::Seg(g @ Seg::Arc { c, r, .. }, _) => {
            // circle crossings, kept when on the arc
            let f0 = p.sub(*c);
            let a2 = d.dot(d);
            let b2 = 2.0 * f0.dot(d);
            let c2 = f0.dot(f0) - r * r;
            let disc = b2 * b2 - 4.0 * a2 * c2;
            if disc < 0.0 {
                return out;
            }
            let sq = disc.sqrt();
            for t in [(-b2 - sq) / (2.0 * a2), (-b2 + sq) / (2.0 * a2)] {
                if t > 1e-9 && t < 1.0 - 1e-9 {
                    let x = p.add(d.mul(t));
                    if on_arc(g, x) {
                        let nrm = x.sub(*c).unit();
                        let sin = u.dot(nrm).abs();
                        out.push((t, sin));
                    }
                }
            }
        }
        Outline::Seg(g @ Seg::Cubic { .. }, _) => {
            // sampled
            let n = 64;
            let mut prev = seg_point(g, 0.0);
            for k in 1..=n {
                let cur = seg_point(g, k as f64 / n as f64);
                let e = cur.sub(prev);
                let den = d.cross(e);
                if den.abs() > 1e-12 {
                    let w = prev.sub(p);
                    let t = w.cross(e) / den;
                    let s = w.cross(d) / den;
                    if t > 1e-9 && t < 1.0 - 1e-9 && s >= 0.0 && s < 1.0 {
                        out.push((t, u.cross(e.unit()).abs()));
                    }
                }
                prev = cur;
            }
        }
        Outline::Ellipse(m, rx, ry, _) => {
            let inv = match invert(m) {
                Some(v) => v,
                None => return out,
            };
            let lp = apply(&inv, p);
            let ld = apply_v(&inv, d);
            if *rx <= 0.0 || *ry <= 0.0 {
                return out;
            }
            let a2 = (ld.x / rx).powi(2) + (ld.y / ry).powi(2);
            let b2 = 2.0 * (lp.x * ld.x / (rx * rx) + lp.y * ld.y / (ry * ry));
            let c2 = (lp.x / rx).powi(2) + (lp.y / ry).powi(2) - 1.0;
            let disc = b2 * b2 - 4.0 * a2 * c2;
            if disc < 0.0 {
                return out;
            }
            let sq = disc.sqrt();
            for t in [(-b2 - sq) / (2.0 * a2), (-b2 + sq) / (2.0 * a2)] {
                if t > 1e-9 && t < 1.0 - 1e-9 {
                    let lx = lp.add(ld.mul(t));
                    // the outward normal in the local frame, mapped back
                    let ln = pt(lx.x / (rx * rx), lx.y / (ry * ry));
                    let nrm = apply_v(&[inv[0], inv[2], inv[1], inv[3], 0.0, 0.0], ln).unit();
                    out.push((t, u.dot(nrm).abs()));
                }
            }
        }
    }
    out
}

fn on_arc(g: &Seg, x: P) -> bool {
    if let Seg::Arc { a, c, sweep, .. } = g {
        let v0 = a.sub(*c);
        let v1 = x.sub(*c);
        let mut ang = v0.cross(v1).atan2(v0.dot(v1));
        if *sweep >= 0.0 {
            if ang < -1e-9 {
                ang += 2.0 * std::f64::consts::PI;
            }
            ang <= sweep + 1e-9
        } else {
            if ang > 1e-9 {
                ang -= 2.0 * std::f64::consts::PI;
            }
            ang >= sweep - 1e-9
        }
    } else {
        false
    }
}

fn outline_sw(o: &Outline) -> f64 {
    match o {
        Outline::Seg(_, sw) => *sw,
        Outline::Ellipse(_, _, _, sw) => *sw,
    }
}

fn halos(ctx: &Ctx, f: usize, lay: &Layout, items: &mut [Item]) {
    if !items.iter().any(|it| it.halo) {
        return;
    }
    let outs = outlines(ctx, f);
    let tips: Vec<P> = items.iter().filter_map(|it| it.tip).chain(lay.tips.iter().copied()).collect();
    let base = match crate::links::path_of(ctx, f) {
        p if p.is_empty() => "lini-halo-".to_string(),
        p => format!("lini-halo-{}-", p),
    };
    let mut seq = 0;
    for it in items.iter_mut() {
        if !it.halo || it.pts.len() < 2 {
            continue;
        }
        let mut segs: Vec<(f64, P, P)> = Vec::new();
        let mut acc = 0.0;
        for w in it.pts.windows(2) {
            let (p, q) = (w[0], w[1]);
            let len = q.sub(p).len();
            if len < 1e-12 {
                continue;
            }
            let u = q.sub(p).mul(1.0 / len);
            for o in &outs {
                for (t, sin) in crossings(p, q, o) {
                    let x = p.add(q.sub(p).mul(t));
                    if tips.iter().any(|tp| tp.sub(x).len() < 1e-6) {
                        continue;
                    }
                    if sin < 1e-9 {
                        continue;
                    }
                    let hl = (outline_sw(o) / 2.0 + HALO_MARGIN) / sin;
                    segs.push((acc + t * len, x.sub(u.mul(hl)), x.add(u.mul(hl))));
                }
            }
            acc += len;
        }
        if segs.is_empty() {
            continue;
        }
        segs.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
        let mut b = BBox::empty();
        for p in &it.pts {
            b.add(p.x, p.y);
        }
        let hw = HALO_W / 2.0;
        let bx = (b.x0 - hw, b.y0 - hw, b.x1 - b.x0 + HALO_W, b.y1 - b.y0 + HALO_W);
        it.mask = Some((format!("{}{}", base, seq), bx, segs.into_iter().map(|s| (s.1, s.2)).collect()));
        seq += 1;
    }
}

// ------------------------------------------------------------ render

fn push_rule(out: &mut Out, slot: &str, rule: &str) {
    let r = (slot.to_string(), rule.to_string());
    if !out.extra_rules.contains(&r) {
        out.extra_rules.push(r);
    }
}

fn pts_str(ps: &[P]) -> String {
    ps.iter().map(|p| format!("{},{}", f4(p.x), f4(p.y))).collect::<Vec<_>>().join(" ")
}

pub fn has_items(ctx: &Ctx, f: usize) -> bool {
    ctx.an.frames.get(&f).map(|fr| !fr.items.is_empty()).unwrap_or(false)
}

// Write frame f's annotations (after its children, before pinned ones).
pub fn render(ctx: &Ctx, f: usize, ind_n: usize, s: &mut String, out: &mut Out) -> Result<(), Diag> {
    let fr = match ctx.an.frames.get(&f) {
        Some(fr) => fr,
        None => return Ok(()),
    };
    let pad = " ".repeat(ind_n);
    let inner = " ".repeat(ind_n + 2);
    let (sx, sy) = (fr.shift.x, fr.shift.y);
    let mut any = (false, false, false, false, false, false, false);
    for it in &fr.items {
        match &it.kind {
            Kind::Text => {
                any.0 = true;
                let p = pt(it.pts[0].x + sx, it.pts[0].y + sy);
                let style = match it.size {
                    Some(sz) => format!(" style=\"font-size: {}px\"", f4(sz)),
                    None => String::new(),
                };
                let rot = if it.rot != 0.0 { format!(" transform=\"rotate({} {} {})\"", f4(it.rot), f4(p.x), f4(p.y)) } else { String::new() };
                s.push_str(&format!(
                    "{}<text class=\"lini-text lini-dim-text\" x=\"{}\" y=\"{}\" dy=\"0.358em\"{}{}>{}</text>\n",
                    pad,
                    f4(p.x),
                    f4(p.y),
                    style,
                    rot,
                    xml_escape(&it.text)
                ));
            }
            Kind::Node(i) => {
                crate::render::render_node(ctx, *i, ind_n, s, out)?;
            }
            k => {
                let prim = if *k == Kind::Polygon { "lini-poly" } else { "lini-line" };
                if *k == Kind::Polygon {
                    any.1 = true;
                } else {
                    any.2 = true;
                }
                if it.cls.contains("lini-dim-line") {
                    any.3 = true;
                }
                if it.cls.contains("lini-ext-line") {
                    any.4 = true;
                }
                if it.cls.contains("lini-marker-datum") {
                    any.6 = true;
                }
                s.push_str(&format!("{}<g class=\"lini-node {} {}\" transform=\"translate({},{})\">\n", pad, it.cls, prim, f4(sx), f4(sy)));
                let mut mask_attr = String::new();
                if let Some((id, (x, y, w, h), segs)) = &it.mask {
                    any.5 = true;
                    let mut m = format!(
                        "<mask id=\"{}\" maskUnits=\"userSpaceOnUse\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"><rect class=\"lini-cut-bg\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"/>",
                        id,
                        f4(*x),
                        f4(*y),
                        f4(*w),
                        f4(*h),
                        f4(*x),
                        f4(*y),
                        f4(*w),
                        f4(*h)
                    );
                    for (a, b) in segs {
                        m.push_str(&format!("<polyline class=\"lini-halo\" fill=\"none\" stroke-width=\"3\" points=\"{}\"/>", pts_str(&[*a, *b])));
                    }
                    m.push_str("</mask>");
                    s.push_str(&format!("{}{}\n", inner, m));
                    mask_attr = format!(" mask=\"url(#{})\"", id);
                }
                match k {
                    Kind::Line => s.push_str(&format!(
                        "{}<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\"{}/>\n",
                        inner,
                        f4(it.pts[0].x),
                        f4(it.pts[0].y),
                        f4(it.pts[1].x),
                        f4(it.pts[1].y),
                        mask_attr
                    )),
                    Kind::Polyline => s.push_str(&format!("{}<polyline points=\"{}\"{}/>\n", inner, pts_str(&it.pts), mask_attr)),
                    _ => s.push_str(&format!("{}<polygon points=\"{}\"{}/>\n", inner, pts_str(&it.pts), mask_attr)),
                }
                for e in &it.extra {
                    s.push_str(&format!("{}{}\n", inner, e));
                }
                s.push_str(&format!("{}</g>\n", pad));
            }
        }
    }
    let (txt, poly, line, dim, ext, halo, datum) = any;
    if txt {
        out.any_text = true;
        push_rule(out, "dim-text", ".lini-dim-text { font-size: 12px; font-weight: var(--lini-link-font-weight); }");
        use_var(&mut out.vars, "link-font-weight");
    }
    if line {
        push_rule(out, "line", ".lini-line { stroke-dasharray: none; }");
    }
    if poly {
        push_rule(out, "poly", ".lini-poly { stroke-dasharray: none; }");
        out.markers = true;
        if fr.items.iter().any(|it| it.cls.contains("lini-marker-dim")) {
            push_rule(out, "marker-dim", ".lini-marker-dim { fill: var(--lini-stroke-dark); }");
            use_var(&mut out.vars, "stroke-dark");
        }
        if datum {
            push_rule(out, "marker-datum", ".lini-marker-datum { fill: var(--lini-stroke-dark); }");
            use_var(&mut out.vars, "stroke-dark");
        }
    }
    if dim {
        push_rule(out, "dim-line", ".lini-dim-line { fill: none; stroke: var(--lini-stroke-dark); stroke-width: 1; }");
        use_var(&mut out.vars, "stroke-dark");
    }
    if ext {
        push_rule(out, "ext-line", ".lini-ext-line { fill: none; stroke: var(--lini-stroke-light); stroke-width: 1; }");
        use_var(&mut out.vars, "stroke-light");
    }
    if halo {
        push_rule(out, "halo-cut-bg", ".lini-cut-bg { fill: white; stroke: none; }");
        push_rule(out, "halo", ".lini-halo { stroke: black; }");
    }
    Ok(())
}

// The root frame's annotations widen the view.
pub fn extend_bbox(ctx: &Ctx, f: usize, b: &mut [f64; 4]) {
    if let Some(fr) = ctx.an.frames.get(&f) {
        if !fr.bbox.is_empty() {
            b[0] = b[0].min(fr.bbox.x0 + fr.shift.x);
            b[1] = b[1].min(fr.bbox.y0 + fr.shift.y);
            b[2] = b[2].max(fr.bbox.x1 + fr.shift.x);
            b[3] = b[3].max(fr.bbox.y1 + fr.shift.y);
        }
    }
}

// Layout-time errors surface once measure is done.
pub fn check(ctx: &Ctx) -> Result<(), Diag> {
    match &ctx.an.error {
        Some(e) => Err(e.clone()),
        None => Ok(()),
    }
}

// ------------------------------------------------------------ frame layout

fn first_error(ctx: &mut Ctx, e: Diag) {
    if ctx.an.error.is_none() {
        ctx.an.error = Some(e);
    }
}

fn ref_of(ctx: &Ctx, f: usize, li: usize, to: bool) -> Result<Ref, Diag> {
    let l = &ctx.links[li];
    let (n, a, ix) = if to { (l.to, &l.to_anchor, l.to_index) } else { (l.from, &l.from_anchor, l.from_index) };
    resolve(ctx, f, n, a.as_deref(), ix).map_err(|m| Diag::error("layout", &m, l.span))
}

// Lay out every annotation written in drawing frame f; `bb` (the parts'
// content box, datum frame) grows to hold them.
pub fn layout(ctx: &mut Ctx, f: usize, bb: &mut BBox) {
    let sts = statements(ctx, f);
    if sts.is_empty() {
        return;
    }
    let mut lay = Layout { geo: *bb, ..Default::default() };
    let mut per: Vec<Vec<Item>> = vec![vec![]; sts.len()];
    let mut errs: Vec<Diag> = Vec::new();
    // pass 1: leaders, round features, datums — they stand off the geometry
    for (k, st) in sts.iter().enumerate() {
        let r = match st.op.as_str() {
            "<-" | "*-" | ">-" => lay_leader_stmt(ctx, f, st, &mut lay, &mut per[k]),
            "(o)" => lay_round_stmt(ctx, f, st, &mut lay, &mut per[k], false),
            _ => Ok(()),
        };
        if let Err(e) = r {
            errs.push(e);
        }
    }
    // pass 2: linear dimensions (and station diameters) pack into rows
    for (k, st) in sts.iter().enumerate() {
        let r = match st.op.as_str() {
            "(-)" => {
                let mut lins = Vec::new();
                let mut bad = None;
                for &li in &st.links {
                    match (ref_of(ctx, f, li, false), ref_of(ctx, f, li, true)) {
                        (Ok(a), Ok(b)) => lins.push(Lin { a, b, li }),
                        (Err(e), _) | (_, Err(e)) => {
                            bad = Some(e);
                            break;
                        }
                    }
                }
                match bad {
                    Some(e) => Err(e),
                    None => lay_linear(ctx, f, st, &lins, &mut lay, &mut per[k]),
                }
            }
            "(o)" => lay_round_stmt(ctx, f, st, &mut lay, &mut per[k], true),
            _ => Ok(()),
        };
        if let Err(e) = r {
            errs.push(e);
        }
    }
    for e in errs {
        first_error(ctx, e);
    }
    let mut items: Vec<Item> = per.into_iter().flatten().collect();
    halos(ctx, f, &lay, &mut items);
    // the frame grows to hold the annotations
    let mut ab = BBox::empty();
    for it in &items {
        item_bbox(ctx, f, it, &mut ab);
    }
    if !ab.is_empty() {
        bb.add(ab.x0, ab.y0);
        bb.add(ab.x1, ab.y1);
    }
    ctx.an.frames.insert(f, Frame { shift: pt(0.0, 0.0), items, bbox: ab });
}

// The frame's centring shift (applied to its children after layout).
pub fn set_shift(ctx: &mut Ctx, f: usize, dx: f64, dy: f64) {
    if let Some(fr) = ctx.an.frames.get_mut(&f) {
        fr.shift = pt(dx, dy);
    }
}

fn item_bbox(ctx: &Ctx, f: usize, it: &Item, b: &mut BBox) {
    match it.kind {
        Kind::Text => {
            let size = it.size.unwrap_or(FONT);
            let w = tw(ctx, f, size, &it.text);
            let c = it.pts[0];
            let (hx, hy) = if (it.rot.abs() - 90.0).abs() < 1e-9 { (size / 2.0, w / 2.0) } else { (w / 2.0, size / 2.0) };
            if it.rot != 0.0 && (it.rot.abs() - 90.0).abs() >= 1e-9 {
                let a = it.rot.to_radians();
                let (s, co) = a.sin_cos();
                for (x, y) in [(-w / 2.0, -size / 2.0), (w / 2.0, -size / 2.0), (w / 2.0, size / 2.0), (-w / 2.0, size / 2.0)] {
                    b.add(c.x + x * co - y * s, c.y + x * s + y * co);
                }
            } else {
                b.add(c.x - hx, c.y - hy);
                b.add(c.x + hx, c.y + hy);
            }
        }
        Kind::Node(_) => {}
        _ => {
            for p in &it.pts {
                b.add(p.x, p.y);
            }
        }
    }
}

fn lay_leader_stmt(ctx: &Ctx, f: usize, st: &St, lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
    for &li in &st.links {
        let r = ref_of(ctx, f, li, false)?;
        match st.op.as_str() {
            ">-" => {
                let letter = st.label.clone().unwrap_or_default();
                lay_datum(ctx, f, st, &r, &letter, lay, out)?;
            }
            _ => {
                let base = if r.feature || r.run.is_some() { thread_of(ctx, &r) } else { None };
                let text = label_text(st, base);
                lay_note(ctx, f, st, &r, &text, lay, out)?;
            }
        }
    }
    Ok(())
}

// The thread a leader's feature carries ("M8×1.25").
fn thread_of(ctx: &Ctx, r: &Ref) -> Option<String> {
    if ctx.nodes[r.node].prim == Prim::Sketch {
        return thread_spec(ctx, r.node);
    }
    None
}

fn lay_round_stmt(ctx: &Ctx, f: usize, st: &St, lay: &mut Layout, out: &mut Vec<Item>, rows: bool) -> Result<(), Diag> {
    for &li in &st.links {
        let r = ref_of(ctx, f, li, false)?;
        let station = r.run.is_some() && r.twin.is_some();
        if station != rows {
            continue;
        }
        if station {
            // a ⌀ station on a revolved run: the run and its twin, measured across
            let (a0, a1) = r.run.unwrap();
            let (b0, b1) = r.twin.unwrap();
            let pa = a0.add(a1).mul(0.5);
            let pb = b0.add(b1).mul(0.5);
            let ra = Ref { run: None, n: None, twin: None, p: pa, ..r.clone() };
            let rb = Ref { run: None, n: None, twin: None, p: pb, ..r.clone() };
            lay_station(ctx, f, st, ra, rb, li, lay, out)?;
        } else {
            lay_round(ctx, f, st, &r, lay, out)?;
        }
    }
    Ok(())
}

// A diameter read across a revolved run and its twin: a dimension row.
fn lay_station(ctx: &Ctx, f: usize, st: &St, a: Ref, b: Ref, li: usize, lay: &mut Layout, out: &mut Vec<Item>) -> Result<(), Diag> {
    let st2 = St { label: None, ..st.clone() };
    let mut tmp = Vec::new();
    // measure as a linear dimension with the ⌀ prefix
    let lins = vec![Lin { a, b, li }];
    lay_linear_pref(ctx, f, &st2, &lins, lay, &mut tmp, "⌀")?;
    out.extend(tmp);
    Ok(())
}

// ------------------------------------------------------------ halos

#[derive(Clone, Debug)]
enum Outline {
    Seg(Seg, f64),
    Ellipse(M, f64, f64, f64),
}

fn outlines(ctx: &Ctx, f: usize) -> Vec<Outline> {
    let mut out = Vec::new();
    let mut stack: Vec<usize> = ctx.nodes[f].children.iter().rev().copied().collect();
    while let Some(i) = stack.pop() {
        let n = &ctx.nodes[i];
        if n.prim == Prim::Text || crate::drawing::is_chrome(ctx, i) || ctx.sk.chrome.contains_key(&i) {
            continue;
        }
        if crate::drawing::is_frame(ctx, i) && !crate::drawing::in_drawing(ctx, i) {
            continue;
        }
        let m = to_frame(ctx, i, f);
        let sw = if ctx.sk.copies.contains(&i) { 0.0 } else { stroke_w(ctx, i) };
        if !is_wrapper(ctx, i) && ctx.comp[i].has_stroke {
            let c = pt(-n.geo_off.0, -n.geo_off.1);
            let (hw, hh) = (n.w / 2.0, n.h / 2.0);
            match n.prim {
                Prim::Oval => {
                    let mm = mul(&m, &[1.0, 0.0, 0.0, 1.0, c.x, c.y]);
                    out.push(Outline::Ellipse(mm, hw, hh, sw));
                }
                Prim::Sketch => {
                    if let Some(l) = ctx.sk.laid.get(&i) {
                        for s in &l.shape.subs {
                            for g in &s.segs {
                                out.push(Outline::Seg(map_seg(&m, g), sw));
                            }
                            if s.closed && !s.end().near(s.start) {
                                out.push(Outline::Seg(map_seg(&m, &Seg::Line { a: s.end(), b: s.start }), sw));
                            }
                        }
                    }
                }
                Prim::Block if n.w > 0.0 && n.h > 0.0 => {
                    let cs = [pt(c.x - hw, c.y - hh), pt(c.x + hw, c.y - hh), pt(c.x + hw, c.y + hh), pt(c.x - hw, c.y + hh)];
                    for k in 0..4 {
                        out.push(Outline::Seg(Seg::Line { a: apply(&m, cs[k]), b: apply(&m, cs[(k + 1) % 4]) }, sw));
                    }
                }
                Prim::Hex if n.w > 0.0 && n.h > 0.0 => {
                    let ps = [pt(-hw, 0.0), pt(-hw / 2.0, -hh), pt(hw / 2.0, -hh), pt(hw, 0.0), pt(hw / 2.0, hh), pt(-hw / 2.0, hh)];
                    for k in 0..6 {
                        out.push(Outline::Seg(Seg::Line { a: apply(&m, ps[k].add(c)), b: apply(&m, ps[(k + 1) % 6].add(c)) }, sw));
                    }
                }
                _ => {}
            }
        }
        if crate::drawing::is_frame(ctx, i) {
            // a nested drawing's parts count too
        }
        for &ch in n.children.iter().rev() {
            stack.push(ch);
        }
    }
    out
}

// Crossings of segment p→q with an outline: (t along p→q, sin of the angle).
fn crossings(p: P, q: P, o: &Outline) -> Vec<(f64, f64)> {
    let d = q.sub(p);
    let len = d.len();
    if len < 1e-12 {
        return vec![];
    }
    let u = d.mul(1.0 / len);
    let mut out = Vec::new();
    match o {
        Outline::Seg(Seg::Line { a, b }, _) => {
            let e = b.sub(*a);
            let den = d.cross(e);
            if den.abs() < 1e-12 {
                return out;
            }
            let w = a.sub(p);
            let t = w.cross(e) / den;
            let s = w.cross(d) / den;
            if t > 1e-9 && t < 1.0 - 1e-9 && s >= -1e-9 && s <= 1.0 + 1e-9 {
                let sin = (u.cross(e.unit())).abs();
                out.push((t, sin));
            }
        }
        Outline::Seg(g @ Seg::Arc { c, r, .. }, _) => {
            // circle crossings, kept when on the arc
            let f0 = p.sub(*c);
            let a2 = d.dot(d);
            let b2 = 2.0 * f0.dot(d);
            let c2 = f0.dot(f0) - r * r;
            let disc = b2 * b2 - 4.0 * a2 * c2;
            if disc < 0.0 {
                return out;
            }
            let sq = disc.sqrt();
            for t in [(-b2 - sq) / (2.0 * a2), (-b2 + sq) / (2.0 * a2)] {
                if t > 1e-9 && t < 1.0 - 1e-9 {
                    let x = p.add(d.mul(t));
                    if on_arc(g, x) {
                        let nrm = x.sub(*c).unit();
                        let sin = u.dot(nrm).abs();
                        out.push((t, sin));
                    }
                }
            }
        }
        Outline::Seg(g @ Seg::Cubic { .. }, _) => {
            // sampled
            let n = 64;
            let mut prev = seg_point(g, 0.0);
            for k in 1..=n {
                let cur = seg_point(g, k as f64 / n as f64);
                let e = cur.sub(prev);
                let den = d.cross(e);
                if den.abs() > 1e-12 {
                    let w = prev.sub(p);
                    let t = w.cross(e) / den;
                    let s = w.cross(d) / den;
                    if t > 1e-9 && t < 1.0 - 1e-9 && s >= 0.0 && s < 1.0 {
                        out.push((t, u.cross(e.unit()).abs()));
                    }
                }
                prev = cur;
            }
        }
        Outline::Ellipse(m, rx, ry, _) => {
            let inv = match invert(m) {
                Some(v) => v,
                None => return out,
            };
            let lp = apply(&inv, p);
            let ld = apply_v(&inv, d);
            if *rx <= 0.0 || *ry <= 0.0 {
                return out;
            }
            let a2 = (ld.x / rx).powi(2) + (ld.y / ry).powi(2);
            let b2 = 2.0 * (lp.x * ld.x / (rx * rx) + lp.y * ld.y / (ry * ry));
            let c2 = (lp.x / rx).powi(2) + (lp.y / ry).powi(2) - 1.0;
            let disc = b2 * b2 - 4.0 * a2 * c2;
            if disc < 0.0 {
                return out;
            }
            let sq = disc.sqrt();
            for t in [(-b2 - sq) / (2.0 * a2), (-b2 + sq) / (2.0 * a2)] {
                if t > 1e-9 && t < 1.0 - 1e-9 {
                    let lx = lp.add(ld.mul(t));
                    // the outward normal in the local frame, mapped back
                    let ln = pt(lx.x / (rx * rx), lx.y / (ry * ry));
                    let nrm = apply_v(&[inv[0], inv[2], inv[1], inv[3], 0.0, 0.0], ln).unit();
                    out.push((t, u.dot(nrm).abs()));
                }
            }
        }
    }
    out
}

fn on_arc(g: &Seg, x: P) -> bool {
    if let Seg::Arc { a, c, sweep, .. } = g {
        let v0 = a.sub(*c);
        let v1 = x.sub(*c);
        let mut ang = v0.cross(v1).atan2(v0.dot(v1));
        if *sweep >= 0.0 {
            if ang < -1e-9 {
                ang += 2.0 * std::f64::consts::PI;
            }
            ang <= sweep + 1e-9
        } else {
            if ang > 1e-9 {
                ang -= 2.0 * std::f64::consts::PI;
            }
            ang >= sweep - 1e-9
        }
    } else {
        false
    }
}

fn outline_sw(o: &Outline) -> f64 {
    match o {
        Outline::Seg(_, sw) => *sw,
        Outline::Ellipse(_, _, _, sw) => *sw,
    }
}

fn halos(ctx: &Ctx, f: usize, lay: &Layout, items: &mut [Item]) {
    if !items.iter().any(|it| it.halo) {
        return;
    }
    let outs = outlines(ctx, f);
    let tips: Vec<P> = items.iter().filter_map(|it| it.tip).chain(lay.tips.iter().copied()).collect();
    let base = match crate::links::path_of(ctx, f) {
        p if p.is_empty() => "lini-halo-".to_string(),
        p => format!("lini-halo-{}-", p),
    };
    let mut seq = 0;
    for it in items.iter_mut() {
        if !it.halo || it.pts.len() < 2 {
            continue;
        }
        let mut segs: Vec<(f64, P, P)> = Vec::new();
        let mut acc = 0.0;
        for w in it.pts.windows(2) {
            let (p, q) = (w[0], w[1]);
            let len = q.sub(p).len();
            if len < 1e-12 {
                continue;
            }
            let u = q.sub(p).mul(1.0 / len);
            for o in &outs {
                for (t, sin) in crossings(p, q, o) {
                    let x = p.add(q.sub(p).mul(t));
                    if tips.iter().any(|tp| tp.sub(x).len() < 1e-6) {
                        continue;
                    }
                    if sin < 1e-9 {
                        continue;
                    }
                    let hl = (outline_sw(o) / 2.0 + HALO_MARGIN) / sin;
                    segs.push((acc + t * len, x.sub(u.mul(hl)), x.add(u.mul(hl))));
                }
            }
            acc += len;
        }
        if segs.is_empty() {
            continue;
        }
        segs.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
        let mut b = BBox::empty();
        for p in &it.pts {
            b.add(p.x, p.y);
        }
        let hw = HALO_W / 2.0;
        let bx = (b.x0 - hw, b.y0 - hw, b.x1 - b.x0 + HALO_W, b.y1 - b.y0 + HALO_W);
        it.mask = Some((format!("{}{}", base, seq), bx, segs.into_iter().map(|s| (s.1, s.2)).collect()));
        seq += 1;
    }
}

// ------------------------------------------------------------ render

fn push_rule(out: &mut Out, slot: &str, rule: &str) {
    let r = (slot.to_string(), rule.to_string());
    if !out.extra_rules.contains(&r) {
        out.extra_rules.push(r);
    }
}

fn pts_str(ps: &[P]) -> String {
    ps.iter().map(|p| format!("{},{}", f4(p.x), f4(p.y))).collect::<Vec<_>>().join(" ")
}

pub fn has_items(ctx: &Ctx, f: usize) -> bool {
    ctx.an.frames.get(&f).map(|fr| !fr.items.is_empty()).unwrap_or(false)
}

// Write frame f's annotations (after its children, before pinned ones).
pub fn render(ctx: &Ctx, f: usize, ind_n: usize, s: &mut String, out: &mut Out) -> Result<(), Diag> {
    let fr = match ctx.an.frames.get(&f) {
        Some(fr) => fr,
        None => return Ok(()),
    };
    let pad = " ".repeat(ind_n);
    let inner = " ".repeat(ind_n + 2);
    let (sx, sy) = (fr.shift.x, fr.shift.y);
    let mut any = (false, false, false, false, false, false, false);
    for it in &fr.items {
        match &it.kind {
            Kind::Text => {
                any.0 = true;
                let p = pt(it.pts[0].x + sx, it.pts[0].y + sy);
                let style = match it.size {
                    Some(sz) => format!(" style=\"font-size: {}px\"", f4(sz)),
                    None => String::new(),
                };
                let rot = if it.rot != 0.0 { format!(" transform=\"rotate({} {} {})\"", f4(it.rot), f4(p.x), f4(p.y)) } else { String::new() };
                s.push_str(&format!(
                    "{}<text class=\"lini-text lini-dim-text\" x=\"{}\" y=\"{}\" dy=\"0.358em\"{}{}>{}</text>\n",
                    pad,
                    f4(p.x),
                    f4(p.y),
                    style,
                    rot,
                    xml_escape(&it.text)
                ));
            }
            Kind::Node(i) => {
                crate::render::render_node(ctx, *i, ind_n, s, out)?;
            }
            k => {
                let prim = if *k == Kind::Polygon { "lini-poly" } else { "lini-line" };
                if *k == Kind::Polygon {
                    any.1 = true;
                } else {
                    any.2 = true;
                }
                if it.cls.contains("lini-dim-line") {
                    any.3 = true;
                }
                if it.cls.contains("lini-ext-line") {
                    any.4 = true;
                }
                if it.cls.contains("lini-marker-datum") {
                    any.6 = true;
                }
                s.push_str(&format!("{}<g class=\"lini-node {} {}\" transform=\"translate({},{})\">\n", pad, it.cls, prim, f4(sx), f4(sy)));
                let mut mask_attr = String::new();
                if let Some((id, (x, y, w, h), segs)) = &it.mask {
                    any.5 = true;
                    let mut m = format!(
                        "<mask id=\"{}\" maskUnits=\"userSpaceOnUse\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"><rect class=\"lini-cut-bg\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"/>",
                        id,
                        f4(*x),
                        f4(*y),
                        f4(*w),
                        f4(*h),
                        f4(*x),
                        f4(*y),
                        f4(*w),
                        f4(*h)
                    );
                    for (a, b) in segs {
                        m.push_str(&format!("<polyline class=\"lini-halo\" fill=\"none\" stroke-width=\"3\" points=\"{}\"/>", pts_str(&[*a, *b])));
                    }
                    m.push_str("</mask>");
                    s.push_str(&format!("{}{}\n", inner, m));
                    mask_attr = format!(" mask=\"url(#{})\"", id);
                }
                match k {
                    Kind::Line => s.push_str(&format!(
                        "{}<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\"{}/>\n",
                        inner,
                        f4(it.pts[0].x),
                        f4(it.pts[0].y),
                        f4(it.pts[1].x),
                        f4(it.pts[1].y),
                        mask_attr
                    )),
                    Kind::Polyline => s.push_str(&format!("{}<polyline points=\"{}\"{}/>\n", inner, pts_str(&it.pts), mask_attr)),
                    _ => s.push_str(&format!("{}<polygon points=\"{}\"{}/>\n", inner, pts_str(&it.pts), mask_attr)),
                }
                for e in &it.extra {
                    s.push_str(&format!("{}{}\n", inner, e));
                }
                s.push_str(&format!("{}</g>\n", pad));
            }
        }
    }
    let (txt, poly, line, dim, ext, halo, datum) = any;
    if txt {
        out.any_text = true;
        push_rule(out, "dim-text", ".lini-dim-text { font-size: 12px; font-weight: var(--lini-link-font-weight); }");
        use_var(&mut out.vars, "link-font-weight");
    }
    if line {
        push_rule(out, "line", ".lini-line { stroke-dasharray: none; }");
    }
    if poly {
        push_rule(out, "poly", ".lini-poly { stroke-dasharray: none; }");
        out.markers = true;
        if fr.items.iter().any(|it| it.cls.contains("lini-marker-dim")) {
            push_rule(out, "marker-dim", ".lini-marker-dim { fill: var(--lini-stroke-dark); }");
            use_var(&mut out.vars, "stroke-dark");
        }
        if datum {
            push_rule(out, "marker-datum", ".lini-marker-datum { fill: var(--lini-stroke-dark); }");
            use_var(&mut out.vars, "stroke-dark");
        }
    }
    if dim {
        push_rule(out, "dim-line", ".lini-dim-line { fill: none; stroke: var(--lini-stroke-dark); stroke-width: 1; }");
        use_var(&mut out.vars, "stroke-dark");
    }
    if ext {
        push_rule(out, "ext-line", ".lini-ext-line { fill: none; stroke: var(--lini-stroke-light); stroke-width: 1; }");
        use_var(&mut out.vars, "stroke-light");
    }
    if halo {
        push_rule(out, "halo-cut-bg", ".lini-cut-bg { fill: white; stroke: none; }");
        push_rule(out, "halo", ".lini-halo { stroke: black; }");
    }
    Ok(())
}

// The root frame's annotations widen the view.
pub fn extend_bbox(ctx: &Ctx, f: usize, b: &mut [f64; 4]) {
    if let Some(fr) = ctx.an.frames.get(&f) {
        if !fr.bbox.is_empty() {
            b[0] = b[0].min(fr.bbox.x0 + fr.shift.x);
            b[1] = b[1].min(fr.bbox.y0 + fr.shift.y);
            b[2] = b[2].max(fr.bbox.x1 + fr.shift.x);
            b[3] = b[3].max(fr.bbox.y1 + fr.shift.y);
        }
    }
}

// Layout-time errors surface once measure is done.
pub fn check(ctx: &Ctx) -> Result<(), Diag> {
    match &ctx.an.error {
        Some(e) => Err(e.clone()),
        None => Ok(()),
    }
}

