fn expr_num(e: &crate::ast::Expr) -> Option<f64> {
    match e {
        crate::ast::Expr::Num(v, _) => Some(*v),
        crate::ast::Expr::Unary(o, b, _) if o == "-" => expr_num(b).map(|v| -v),
