fn expr_term(e: &crate::ast::Expr) -> Option<crate::ast::Term> {
    Some(match e {
        crate::ast::Expr::Ident(s, sp) => crate::ast::Term::Ident(s.clone(), *sp),
        crate::ast::Expr::Var(s, sp) => crate::ast::Term::Var(s.clone(), *sp),
        crate::ast::Expr::Hash(s, sp) => crate::ast::Term::Hash(s.clone(), *sp),
        crate::ast::Expr::Call(n, a, sp) => crate::ast::Term::Call(n.clone(), a.clone(), *sp),
        _ => return None,
    })
}

// The pattern id of a hatch: a hash of its parameters.
fn hatch_id(angle: &str, pitch: &str, color: &str) -> String {
    format!("lini-hatch-{}", crate::util::hash8(&format!("{},{},{}", angle, pitch, color)))
}

// `fill: hatch(angle, pitch[, colour])` → url(#…), registering the pattern.
pub fn hatch_css(args: &[crate::ast::Expr], vars: &mut Vec<String>, span: Span) -> Result<String, Diag> {
    let angle = args.first().and_then(expr_num).unwrap_or(45.0);
    let pitch = args.get(1).and_then(expr_num).unwrap_or(6.0);
    let color = match args.get(2).and_then(expr_term) {
        Some(t) => crate::style::color_css(&t, vars, span)?,
        None => {
            use_var(vars, "stroke");
            "var(--lini-stroke)".to_string()
        }
    };
    let id = hatch_id(&f4(angle), &f4(pitch), &color);
    let def = format!(
        "<pattern id=\"{}\" patternUnits=\"userSpaceOnUse\" width=\"{}\" height=\"{}\" patternTransform=\"rotate({})\"><g style=\"stroke: {}\" stroke-width=\"0.75\"><line x1=\"{}\" y1=\"0\" x2=\"{}\" y2=\"{}\"/></g></pattern>",
        id,
        f4(pitch),
        f4(pitch),
        f4(angle),
        color,
        f4(pitch / 2.0),
        f4(pitch / 2.0),
        f4(pitch)
    );
    HATCHES.with(|h| {
        let mut h = h.borrow_mut();
        if !h.iter().any(|e| e.0 == id) {
            h.push((id.clone(), def));
        }
    });
    Ok(format!("url(#{})", id))
}

// The hatch patterns registered so far (drained).
pub fn take_hatches() -> Vec<String> {
    HATCHES.with(|h| h.borrow_mut().drain(..).map(|e| e.1).collect())
}

