// sampled) — the region a fill paints.
fn inside_region(rings: &[Vec<Seg>], p: P) -> bool {
    let mut inside = false;
    for segs in rings {
        let mut pts: Vec<P> = Vec::new();
        for g in segs {
            match g {
                Seg::Line { a, b } => {
                    pts.push(*a);
                    pts.push(*b);
                }
                _ => {
                    for k in 0..=16 {
                        pts.push(seg_point(g, k as f64 / 16.0));
                    }
                }
            }
        }
        let n = pts.len();
        if n < 3 {
            continue;
        }
        let mut j = n - 1;
        for i in 0..n {
            let (a, b) = (pts[i], pts[j]);
            if (a.y > p.y) != (b.y > p.y) {
                let x = (b.x - a.x) * (p.y - a.y) / (b.y - a.y) + a.x;
                if p.x < x {
                    inside = !inside;
                }
            }
            j = i;
        }
    }
    inside
}

// The parameter (0..1) of a point on an arc, if it lies on it.
fn arc_param(g: &Seg, x: P) -> Option<f64> {
    if let Seg::Arc { a, c, sweep, .. } = g {
        let v0 = a.sub(*c);
        let v1 = x.sub(*c);
        let mut ang = v0.cross(v1).atan2(v0.dot(v1));
        if *sweep >= 0.0 {
            if ang < -1e-9 {
                ang += 2.0 * std::f64::consts::PI;
            }
            if ang <= sweep + 1e-9 {
                return Some((ang / sweep).clamp(0.0, 1.0));
            }
        } else {
            if ang > 1e-9 {
                ang -= 2.0 * std::f64::consts::PI;
            }
            if ang >= sweep - 1e-9 {
                return Some((ang / sweep).clamp(0.0, 1.0));
            }
        }
    }
    None
}

// A point just inside a segment from one end (for side tests at vertices).
fn near_end(g: &Seg, at_start: bool) -> P {
    let t = if at_start { 1e-3 } else { 1.0 - 1e-3 };
    seg_point(g, t)
}

// Crossings of segment p→q with an outline: (t along p→q, sin of the angle).
// A crossing at a vertex counts once, and only where the outline passes
// from one side of the line to the other.
fn crossings(p: P, q: P, o: &Outline) -> Vec<(f64, f64)> {
    let d = q.sub(p);
    if d.len() < 1e-12 {
        return vec![];
    }
    let mut out = Vec::new();
    match o {
        Outline::Path(segs, closed, _, region) => {
            let n = segs.len();
            // does the line arrive at x from outside the node's filled region?
            let from_outside = |x: P| -> bool {
                let probe = x.sub(d.unit().mul(1e-3));
                !inside_region(region, probe)
            };
            for k in 0..n {
                for (t, s, sin) in seg_hits(p, q, &segs[k]) {
                    if s > 1e-9 && s < 1.0 - 1e-9 {
                        out.push((t, sin));
                        continue;
                    }
                    let x = p.add(d.mul(t));
                    // a neighbour running along the line: the vertex counts where
                    // the line goes on along that edge
                    let along = |g: &Seg| -> Option<bool> {
                        if let Seg::Line { a, b } = g {
                            let e = b.sub(*a);
                            if e.len() > 1e-12 && d.cross(e).abs() < 1e-9 * d.len() * e.len() && side_of(p, d, *a).abs() < 1e-6 * d.len() {
                                let far = if a.sub(x).len() > b.sub(x).len() { *a } else { *b };
                                return Some(far.sub(x).dot(d) > 0.0);
                            }
                        }
                        None
                    };
                    if s >= 1.0 - 1e-9 {
                        // the next segment's start owns this vertex, unless it
                        // runs along the line
                        let next = if k + 1 < n {
                            Some(&segs[k + 1])
                        } else if *closed {
                            Some(&segs[0])
                        } else {
                            None
                        };
                        let _ = next;
                        continue;
                    }
                    // at this segment's start vertex: a crossing only where the
                    // outline passes from one side of the line to the other
                    let prev = if k > 0 {
                        Some(&segs[k - 1])
                    } else if *closed {
                        Some(&segs[n - 1])
                    } else {
                        None
                    };
                    if let Some(pg) = prev {
                        match along(pg) {
                            // the line runs along the edge here: no crossing
                            // (junctions between shapes' edges are their own case)
                            Some(_) => {
                                let _ = from_outside(x);
                            }
                            None => {
                                let before = near_end(pg, false);
                                let after = near_end(&segs[k], true);
                                let (sb, sa) = (side_of(p, d, before), side_of(p, d, after));
                                if sb * sa < 0.0 {
                                    out.push((t, sin));
                                }
                            }
                        }
                    }
                }
            }
        }
        Outline::Box(segs, _) => {
            // a nested frame's box: every touch counts, corners once
            let mut seen: Vec<f64> = Vec::new();
            for g in segs {
                for (t, _s, sin) in seg_hits(p, q, g) {
                    if seen.iter().any(|&x| (x - t).abs() < 1e-9) {
                        continue;
                    }
                    seen.push(t);
                    out.push((t, sin));
                }
            }
        }
        Outline::Ellipse(m, rx, ry, _) => {
            let u = d.unit();
            let inv = match invert(m) {
                Some(v) => v,
                None => return out,
            };
            let lp = apply(&inv, p);
            let ld = apply_v(&inv, d);
            if *rx <= 0.0 || *ry <= 0.0 {
                return out;
            }
            let a2 = (ld.x / rx).powi(2) + (ld.y / ry).powi(2);
            let b2 = 2.0 * (lp.x * ld.x / (rx * rx) + lp.y * ld.y / (ry * ry));
            let c2 = (lp.x / rx).powi(2) + (lp.y / ry).powi(2) - 1.0;
            let disc = b2 * b2 - 4.0 * a2 * c2;
            if disc <= 0.0 {
                return out;
            }
            let sq = disc.sqrt();
            for t in [(-b2 - sq) / (2.0 * a2), (-b2 + sq) / (2.0 * a2)] {
                if t > 1e-9 && t < 1.0 - 1e-9 {
                    let lx = lp.add(ld.mul(t));
                    let ln = pt(lx.x / (rx * rx), lx.y / (ry * ry));
                    let nrm = apply_v(&[inv[0], inv[2], inv[1], inv[3], 0.0, 0.0], ln).unit();
                    out.push((t, u.dot(nrm).abs()));
                }
            }
        }
    }
    out
}
fn on_arc(g: &Seg, x: P) -> bool {
    if let Seg::Arc { a, c, sweep, .. } = g {
        let v0 = a.sub(*c);
        let v1 = x.sub(*c);
        let mut ang = v0.cross(v1).atan2(v0.dot(v1));
        if *sweep >= 0.0 {
            if ang < -1e-9 {
                ang += 2.0 * std::f64::consts::PI;
            }
            ang <= sweep + 1e-9
        } else {
            if ang > 1e-9 {
                ang -= 2.0 * std::f64::consts::PI;
            }
            ang >= sweep - 1e-9
        }
    } else {
        false
    }
}

fn outline_sw(o: &Outline) -> f64 {
    match o {
        Outline::Path(_, _, sw, _) => *sw,
        Outline::Box(_, sw) => *sw,
        Outline::Ellipse(_, _, _, sw) => *sw,
    }
}

fn halos(ctx: &Ctx, f: usize, lay: &Layout, items: &mut [Item]) {
    if !items.iter().any(|it| it.halo) {
        return;
    }
    let outs = outlines(ctx, f);
    let tips: Vec<P> = items.iter().filter_map(|it| it.tip).chain(lay.tips.iter().copied()).collect();
    let base = match crate::links::path_of(ctx, f) {
        p if p.is_empty() => "lini-halo-".to_string(),
        p => format!("lini-halo-{}-", p),
    };
    let mut seq = 0;
    for it in items.iter_mut() {
        if !it.halo || it.pts.len() < 2 {
            continue;
        }
        let mut segs: Vec<(f64, P, P)> = Vec::new();
        let mut acc = 0.0;
        for w in it.pts.windows(2) {
            let (p, q) = (w[0], w[1]);
            let len = q.sub(p).len();
            if len < 1e-12 {
                continue;
            }
            let u = q.sub(p).mul(1.0 / len);
            // where the line runs on along one shape's edge into another's
            for (t, sw) in junctions(p, q, &outs) {
                let x = p.add(q.sub(p).mul(t));
                let hl = sw / 2.0 + HALO_MARGIN;
                segs.push((acc + t * len, x.sub(u.mul(hl)), x.add(u.mul(hl))));
            }
            for o in &outs {
                for (t, sin) in crossings(p, q, o) {
                    let x = p.add(q.sub(p).mul(t));
                    // under the line's own arrowheads, or where a leader lands, no halo
                    if it.own_tips.iter().any(|tp| tp.sub(x).len() <= ARROW_L + 1e-6) || tips.iter().any(|tp| tp.sub(x).len() < 1e-6) {
                        continue;
                    }
                    // a tangent touch is no crossing
                    if sin < 1e-4 {
                        continue;
                    }
                    let hl = (outline_sw(o) / 2.0 + HALO_MARGIN) / sin;
                    segs.push((acc + t * len, x.sub(u.mul(hl)), x.add(u.mul(hl))));
                }
            }
            acc += len;
        }
        if segs.is_empty() {
            continue;
        }
        segs.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
        // overlapping halos merge
        let mut merged: Vec<(f64, P, P)> = Vec::new();
        for sg in segs {
            if let Some(last) = merged.last_mut() {
                let lu = last.2.sub(last.1);
                let reach = sg.1.sub(last.1).dot(lu.unit());
                if reach <= lu.len() + 1e-9 {
                    if sg.2.sub(last.1).dot(lu.unit()) > lu.len() {
                        last.2 = sg.2;
                    }
                    continue;
                }
            }
            merged.push(sg);
        }
        let segs = merged;
        let mut b = BBox::empty();
        for p in it.pts.iter().chain(it.mask_pts.iter()) {
            b.add(p.x, p.y);
        }
        let hw = HALO_W / 2.0;
        let bx = (b.x0 - hw, b.y0 - hw, b.x1 - b.x0 + HALO_W, b.y1 - b.y0 + HALO_W);
        it.mask = Some((format!("{}{}", base, seq), bx, segs.into_iter().map(|s| (s.1, s.2)).collect()));
        seq += 1;
    }
}

