python3 - <<'EOF'
import re
p='src/annot.rs'
s=open(p).read()
start=s.index("// Crossings of segment p→q with an outline: (t along p→q, sin of the angle).\n// A crossing at a vertex counts once")
end=s.index("        Outline::Box(segs, _) => {", start)
new='''// Crossings of segment p→q with an outline: (t along p→q, sin of the angle).
// Every edge meeting the line counts, in edge order — at a vertex both edges
// do — except at an open path's ends and at a vertex whose other edge runs
// along the line.
fn crossings(p: P, q: P, o: &Outline) -> Vec<(f64, f64)> {
    let d = q.sub(p);
    if d.len() < 1e-12 {
        return vec![];
    }
    let mut out = Vec::new();
    match o {
        Outline::Path(segs, closed, _, _) => {
            let n = segs.len();
            // an edge running along the line
            let along = |g: &Seg| -> bool {
                if let Seg::Line { a, b } = g {
                    let e = b.sub(*a);
                    return e.len() > 1e-12 && d.cross(e).abs() < 1e-9 * d.len() * e.len() && side_of(p, d, *a).abs() < 1e-6 * d.len();
                }
                false
            };
            for k in 0..n {
                for (t, s, sin) in seg_hits(p, q, &segs[k]) {
                    if s > 1e-9 && s < 1.0 - 1e-9 {
                        out.push((t, sin));
                        continue;
                    }
                    // at a vertex: the edge on its other side
                    let other = if s >= 1.0 - 1e-9 {
                        if k + 1 < n {
                            Some(&segs[k + 1])
                        } else if *closed {
                            Some(&segs[0])
                        } else {
                            None
                        }
                    } else if k > 0 {
                        Some(&segs[k - 1])
                    } else if *closed {
                        Some(&segs[n - 1])
                    } else {
                        None
                    };
                    match other {
                        Some(g) if !along(g) => out.push((t, sin)),
                        _ => {}
                    }
                }
            }
        }
'''
s=s[:start]+new+s[end:]
open(p,'w').write(s)
