1958:fn arc_param(g: &Seg, x: P) -> Option<f64> {
1959-    if let Seg::Arc { a, c, sweep, .. } = g {
1960-        let v0 = a.sub(*c);
1961-        let v1 = x.sub(*c);
1962-        let mut ang = v0.cross(v1).atan2(v0.dot(v1));
1963-        if *sweep >= 0.0 {
1964-            if ang < -1e-9 {
1965-                ang += 2.0 * std::f64::consts::PI;
1966-            }
1967-            if ang <= sweep + 1e-9 {
1968-                return Some((ang / sweep).clamp(0.0, 1.0));
1969-            }
1970-        } else {
1971-            if ang > 1e-9 {
1972-                ang -= 2.0 * std::f64::consts::PI;
1973-            }
1974-            if ang >= sweep - 1e-9 {
1975-                return Some((ang / sweep).clamp(0.0, 1.0));
1976-            }
1977-        }
1978-    }
1979-    None
1980-}
