    pub fn resolve_links(&mut self) -> Result<(), Diag> {
        let pending = std::mem::take(&mut self.pending_links);
        for (container, l, idx) in pending {
            for c in &l.classes {
                if self.sheet.class(c).is_none() {
                    return Err(Diag::error("unknown-class", &format!("unknown class '.{}'", c), l.span));
                }
            }
            // annotations [SPEC 15.5]: placement, strict endpoints, one-ended forms
            let in_dwg = crate::annot::stmt_in_drawing(self, container);
            crate::annot::check_stmt(self, container, &l, in_dwg)?;
            if in_dwg {
                crate::annot::build_carried(self, container, &l)?;
            }
            let mut groups: Vec<Vec<(usize, Option<String>, Option<u32>)>> = Vec::new();
            for g in &l.groups {
                let mut v = Vec::new();
                for ep in g {
                    match ep {
                        Endpoint::Path(p) => {
                            let n = if in_dwg { crate::annot::endpoint_strict(self, container, p)? } else { self.endpoint(container, p)? };
                            v.push((n, p.anchor.clone(), p.index));
                        }
                        Endpoint::Node(_) | Endpoint::Text(..) => {}
                    }
                }
                groups.push(v);
            }
            if groups.len() == 1 && crate::annot::one_ended_ok(&l.ops.first().map(|o| o.0.clone()).unwrap_or_default(), in_dwg) {
                let op = l.ops[0].0.clone();
                for a in &groups[0] {
                    self.links.push(Link {
                        from: a.0,
                        to: a.0,
                        op: op.clone(),
                        label: l.label.as_ref().map(|x| x.0.clone()),
                        labels: l.labels.clone().unwrap_or_default(),
                        classes: l.classes.clone(),
                        style: l.style.clone().unwrap_or_default(),
                        from_anchor: a.1.clone(),
                        to_anchor: a.1.clone(),
                        from_index: a.2,
                        to_index: a.2,
                        span: l.span,
                        stmt_index: idx,
                        container,
                        one_ended: true,
                    });
                }
                continue;
            }
            if groups.len() < 2 {
                return Err(Diag::error("chain-too-short", "link requires at least two endpoints", l.span));
            }
            for k in 0..groups.len() - 1 {
                let op = l.ops.get(k).map(|o| o.0.clone()).unwrap_or_default();
                for a in &groups[k] {
                    for b in &groups[k + 1] {
                        self.links.push(Link {
                            from: a.0,
                            to: b.0,
                            op: op.clone(),
                            label: l.label.as_ref().map(|x| x.0.clone()),
                            labels: l.labels.clone().unwrap_or_default(),
                            classes: l.classes.clone(),
                            style: l.style.clone().unwrap_or_default(),
                            from_anchor: a.1.clone(),
                            to_anchor: b.1.clone(),
                            from_index: a.2,
                            to_index: b.2,
                            span: l.span,
                            stmt_index: idx,
                            container,
                            one_ended: false,
                        });
                    }
                }
            }
        }
        Ok(())
    }
