            _ => {
                let name = ctx.nodes[l.from].id.clone().unwrap_or_default();
                return Err(Diag::error(
                    "layout",
                    &format!("'(o)' can't pick an axis on '{}' — anchor a side ('{}:top (o)') or a segment", name, name),
                    st.span,
                ));
            }
        }
    }
    Ok(())
}

