fn lay_round_stmt(ctx: &Ctx, f: usize, st: &St, lay: &mut Layout, out: &mut Vec<Item>, rows: bool) -> Result<(), Diag> {
    for &li in &st.links {
        let r = ref_of(ctx, f, li, false)?;
