767	fn lay_linear_pref(ctx: &Ctx, f: usize, st: &St, lins: &[Lin], lay: &mut Layout, out: &mut Vec<Item>, prefix: &str) -> Result<(), Diag> {
768	    if lins.is_empty() {
769	        return Ok(());
770	    }
771	    let project = st.ident("project");
772	    let ax = match dim_axis(&lins[0].a, &lins[0].b, project.as_deref()) {
773	        Ok(a) => a,
774	        Err(_) => {
775	            let l = &ctx.links[lins[0].li];
776	            let name = |n: usize, a: &Option<String>| {
777	                let p = crate::links::path_of(ctx, n);
778	                match a {
779	                    Some(a) => format!("{}:{}", p, a),
780	                    None => p,
781	                }
782	            };
783	            let msg = format!(
784	                "'{} (-) {}' — perpendicular faces have no shared normal; the angle between edges is '(<)'",
785	                name(l.from, &l.from_anchor),
786	                name(l.to, &l.to_anchor)
787	            );
788	            return Err(Diag::error("layout", &msg, st.span));
789	        }
790	    };
791	    let k = crate::drawing::ps(ctx, f);
792	    if let Axis::A(_) = ax {
793	        for lin in lins {
794	            lay_aligned(ctx, f, st, lin, k, lay, out)?;
795	        }
796	        return Ok(());
797	    }
798	    let side: &'static str = match st.ident("side") {
799	        Some(s) => side_static(&s),
800	        None => {
801	            if ax == Axis::X {
802	                "bottom"
803	            } else {
804	                "right"
805	            }
806	        }
807	    };
808	    let o = outward(side);
809	    // texts first: the row band depends on them
810	    let mut texts = Vec::new();
811	    let mut lo = f64::INFINITY;
812	    let mut hi = f64::NEG_INFINITY;
813	    for lin in lins {
814	        let (pa, pb) = (along(ax, lin.a.p), along(ax, lin.b.p));
815	        let extra = break_extra(ctx, f, &lin.a, &lin.b, ax);
816	        let t = dim_text(ctx, f, st, ((pb - pa).abs() + extra) / k, prefix)?;
817	        lo = lo.min(pa.min(pb));
818	        hi = hi.max(pa.max(pb));
819	        texts.push(t);
820	    }
821	    let carried = carried_nodes(ctx, f, st.span);
822	    // the band about the dim line along the outward axis, from a probe layout
823	    let probe = linear_items(ctx, f, ax, o, lins, &texts, &carried, 0.0);
824	    let (mut smin, mut smax) = (f64::INFINITY, f64::NEG_INFINITY);
825	    for it in &probe {
826	        // the extension lines and a tolerance stack stay out of the band
827	        if it.cls.contains("lini-ext-line") || (it.kind == Kind::Text && it.size.is_some()) {
828	            continue;
829	        }
830	        let mut b = BBox::empty();
831	        item_bbox(ctx, f, it, &mut b);
832	        if let Kind::Node(i) = it.kind {
833	            node_box_at(ctx, i, it.pts[0], &mut b);
834	        }
835	        if b.is_empty() {
836	            continue;
837	        }
838	        for (x, y) in [(b.x0, b.y0), (b.x1, b.y1)] {
839	            let s = pt(x, y).dot(o);
840	            smin = smin.min(s);
841	            smax = smax.max(s);
842	        }
843	    }
844	    smax = smax.max(EXT_OVER);
845	    let base = extent(lay, side, lo, hi);
846	    let rows = lay.rows.entry(side).or_default();
847	    let mut row_ix = None;
848	    for (ri, r) in rows.iter().enumerate() {
849	        if r.spans.iter().all(|&(a, b)| !(lo < b - 1e-6 && a < hi - 1e-6)) {
850	            row_ix = Some(ri);
851	            break;
852	        }
853	    }
854	    let ri = match row_ix {
855	        Some(ri) => ri,
856	        None => {
857	            let near = match rows.last() {
858	                Some(r) => r.far,
859	                None => base,
860	            } + CLEAR;
861	            let l = near - smin;
862	            rows.push(Row { l, far: l + smax, spans: vec![] });
863	            rows.len() - 1
864	        }
865	    };
866	    rows[ri].spans.push((lo, hi));
