878	// A carried node's outer box with its datum at `at`.
879	fn node_box_at(ctx: &Ctx, i: usize, at: P, b: &mut BBox) {
880	    let n = &ctx.nodes[i];
881	    let sw = stroke_w(ctx, i);
882	    let (w, h) = (n.w + sw, n.h + sw);
883	    let c = pt(at.x - n.geo_off.0, at.y - n.geo_off.1);
884	    b.add(c.x - w / 2.0, c.y - h / 2.0);
885	    b.add(c.x + w / 2.0, c.y + h / 2.0);
886	}
887	
888	// Carried nodes stack under a text (screen-down), 3 apart: their datums.
889	fn stack_under(ctx: &Ctx, carried: &[usize], c: P, half_y: f64) -> Vec<Item> {
890	    let mut y = c.y + half_y + 3.0;
891	    let mut out = Vec::new();
892	    for &i in carried {
893	        let n = &ctx.nodes[i];
894	        let sw = stroke_w(ctx, i);
895	        let h = n.h + sw;
896	        let center = pt(c.x, y + h / 2.0);
897	        let at = pt(center.x + n.geo_off.0, center.y + n.geo_off.1);
898	        let mut it = Item::new(Kind::Node(i), "lini-carried", vec![at]);
899	        it.halo = false;
900	        out.push(it);
901	        y += h + 3.0;
902	    }
903	    out
904	}
905	
906	fn linear_items(ctx: &Ctx, f: usize, ax: Axis, o: P, lins: &[Lin], texts: &[DimText], carried: &[usize], lpos: f64) -> Vec<Item> {
907	    let mut out = Vec::new();
908	    for (k, (lin, t)) in lins.iter().zip(texts.iter()).enumerate() {
909	        let on_line = |p: P| -> P {
910	            match ax {
911	                Axis::X => pt(p.x, lpos),
912	                _ => pt(lpos, p.y),
913	            }
914	        };
915	        let (a, b) = (&lin.a, &lin.b);
916	        // extension lines: a tagged run along them starts at its end nearest the row
917	        for r in [a, b] {
918	            let q = on_line(r.p);
919	            let from = match (&r.tag, r.run) {
920	                (Some(_), Some((r0, r1))) if r1.sub(r0).unit().cross(o).abs() < 1e-9 => {
921	                    if r0.dot(o) > r1.dot(o) {
922	                        r0
923	                    } else {
924	                        r1
925	                    }
926	                }
927	                _ => r.p,
928	            };
929	            let s = from.add(o.mul(EXT_GAP));
930	            let e = q.add(o.mul(EXT_OVER));
931	            let mut it = Item::new(Kind::Line, "lini-ext-line", vec![s, e]);
932	            it.halo = true;
933	            out.push(it);
934	        }
935	        // the dim line and its arrows run in increasing x / y
936	        let (qa, qb) = {
937	            let (p1, p2) = (on_line(a.p), on_line(b.p));
938	            if along(ax, p1) <= along(ax, p2) {
939	                (p1, p2)
940	            } else {
941	                (p2, p1)
942	            }
