1025	// Gap between two boxes (negative when they overlap on both axes).
1026	fn box_gap(a: &BBox, b: &BBox) -> f64 {
1027	    let gx = (a.x0 - b.x1).max(b.x0 - a.x1);
1028	    let gy = (a.y0 - b.y1).max(b.y0 - a.y1);
1029	    gx.max(gy)
1030	}
1031	
1032	// How far the ray from p (inside or on the box) runs before leaving it.
1033	fn exit_t(b: &BBox, p: P, u: P) -> f64 {
1034	    let mut t = f64::INFINITY;
1035	    if u.x > 1e-12 {
1036	        t = t.min((b.x1 - p.x) / u.x);
1037	    } else if u.x < -1e-12 {
1038	        t = t.min((b.x0 - p.x) / u.x);
1039	    }
1040	    if u.y > 1e-12 {
1041	        t = t.min((b.y1 - p.y) / u.y);
1042	    } else if u.y < -1e-12 {
1043	        t = t.min((b.y0 - p.y) / u.y);
1044	    }
1045	    if t.is_finite() {
1046	        t.max(0.0)
1047	    } else {
1048	        0.0
1049	    }
1050	}
1051	
1052	// A note's box: the landing runs from the knee along h, the text `lead` out.
1053	fn note_box(knee: P, h: f64, lead: f64, w: f64, hh: f64) -> BBox {
1054	    let x0 = knee.x + h * lead;
1055	    let x1 = x0 + h * w;
1056	    let mut b = BBox::empty();
1057	    b.add(x0.min(x1), knee.y - hh);
1058	    b.add(x0.max(x1), knee.y + hh);
1059	    b
1060	}
1061	
1062	// The knee on the ray tip + t·u: out of the geometry box by NOTE_OFFSET, then
1063	// further until the note's box (`rel`, about the knee) clears every obstacle
1064	// by its clearance.
1065	fn knee_clear(obs: &[(BBox, f64)], geo: &BBox, tip: P, u: P, rel: &BBox) -> (P, f64) {
1066	    let h = if u.x < -1e-9 { -1.0 } else { 1.0 };
1067	    let at = |t: f64| tip.add(u.mul(t));
1068	    let mut t = exit_t(geo, tip, u) + NOTE_OFFSET;
1069	    let boxed = |t: f64| -> BBox {
1070	        let k = at(t);
1071	        let mut b = BBox::empty();
1072	        b.add(k.x + rel.x0, k.y + rel.y0);
1073	        b.add(k.x + rel.x1, k.y + rel.y1);
1074	        b
1075	    };
1076	    for _ in 0..32 {
1077	        let mut changed = false;
1078	        for (ob, c) in obs {
1079	            if ob.is_empty() || box_gap(&boxed(t), ob) >= c - 1e-9 {
1080	                continue;
1081	            }
1082	            let mut need = f64::INFINITY;
1083	            if u.x > 1e-9 {
1084	                need = need.min((ob.x1 + c - rel.x0 - tip.x) / u.x);
1085	            } else if u.x < -1e-9 {
1086	                need = need.min((ob.x0 - c - rel.x1 - tip.x) / u.x);
1087	            }
1088	            if u.y > 1e-9 {
1089	                need = need.min((ob.y1 + c - rel.y0 - tip.y) / u.y);
1090	            } else if u.y < -1e-9 {
1091	                need = need.min((ob.y0 - c - rel.y1 - tip.y) / u.y);
1092	            }
1093	            if need.is_finite() && need > t + 1e-9 {
1094	                t = need;
1095	                changed = true;
1096	            }

