pub fn weight_num(v: &Value) -> u32 {
    match single_term(v) {
        Some(Term::Ident(n, _)) => match n.as_str() {
            "bold" => 700,
            "semibold" => 600,
            "medium" => 500,
            _ => 400,
        },
        Some(Term::Num(x, _, _)) => *x as u32,
        Some(Term::Var(n, _)) => match n.as_str() {
            "caption-font-weight" | "link-font-weight" => 400,
            "font-weight" => 500,
            _ => 500,
        },
        _ => 500,
    }
}

