                let hl = (h.2 / 2.0 + HALO_MARGIN) / h.1;
                let (h0, h1) = (x.sub(u.mul(hl)), x.add(u.mul(hl)));
                // a halo reaching under the line's own arrowheads (their
                // boxes), or where a leader lands: none
                let under = |tp: &P| match heads.iter().find(|(t, _)| t.sub(*tp).len() < 1e-9) {
                    Some((_, b)) => tp.sub(x).len() <= ARROW_L + 1e-6 || seg_meets_box(h0, h1, b),
                    None => tp.sub(x).len() <= ARROW_L + 1e-6,
                };
                if it.own_tips.iter().any(under) || tips.iter().any(|tp| tp.sub(x).len() < 1e-6) {
                    continue;
                }
                segs.push((acc + h.0 * len, h0, h1));''','''                let x = p.add(q.sub(p).mul(h.0));
                let hl = (h.2 / 2.0 + HALO_MARGIN) / h.1;
