                    None => tp.sub(x).len() <= ARROW_L + 1e-6,
                };
                let drop = it.own_tips.iter().any(under) || tips.iter().any(|tp| tp.sub(x).len() < 1e-6);
                segs.push((acc + h.0 * len, h0, h1, drop));''')
