s=open(p).read()
def rep(old,new):
    global s
    assert old in s, old[:70]
    s=s.replace(old,new,1)

# collect arrowhead triangles (all) once
rep('''    // the arrowheads' boxes, by tip
    let heads: Vec<(P, BBox)> = items''','''    // the arrowheads' triangles (another line's halo keeps 2 off them)
    let tris: Vec<(P, Vec<P>)> = items.iter().filter(|it| it.kind == Kind::Polygon && it.tip.is_some() && it.pts.len() == 3).map(|it| (it.tip.unwrap(), it.pts.clone())).collect();
    // the arrowheads' boxes, by tip
    let heads: Vec<(P, BBox)> = items''')
rep('''                let drop = stub || it.own_tips.iter().any(under) || tips.iter().any(|tp| tp.sub(x).len() < 1e-6);''','''                let near_other = tris.iter().any(|(tp, tri)| !it.own_tips.iter().any(|o| o.sub(*tp).len() < 1e-9) && seg_tri_dist(h0, h1, tri) < HALO_W / 2.0 + HALO_MARGIN);
                let drop = stub || near_other || it.own_tips.iter().any(under) || tips.iter().any(|tp| tp.sub(x).len() < 1e-6);''')
rep('''// Does segment a→b touch box b (edges included)?''','''// The distance between segment a→b and a triangle (0 when they meet).
fn seg_tri_dist(a: P, b: P, tri: &[P]) -> f64 {
    let inside = |p: P| -> bool {
        let s0 = tri[1].sub(tri[0]).cross(p.sub(tri[0]));
        let s1 = tri[2].sub(tri[1]).cross(p.sub(tri[1]));
        let s2 = tri[0].sub(tri[2]).cross(p.sub(tri[2]));
        (s0 >= 0.0 && s1 >= 0.0 && s2 >= 0.0) || (s0 <= 0.0 && s1 <= 0.0 && s2 <= 0.0)
    };
    if inside(a) || inside(b) {
        return 0.0;
    }
    let pt_seg = |p: P, s0: P, s1: P| -> f64 {
        let d = s1.sub(s0);
        let l2 = d.dot(d);
        let t = if l2 < 1e-18 { 0.0 } else { (p.sub(s0).dot(d) / l2).clamp(0.0, 1.0) };
        p.sub(s0.add(d.mul(t))).len()
    };
    let mut best = f64::INFINITY;
    for k in 0..3 {
        let (e0, e1) = (tri[k], tri[(k + 1) % 3]);
        // crossing edges
        let d1 = b.sub(a);
        let d2 = e1.sub(e0);
        let den = d1.cross(d2);
        if den.abs() > 1e-12 {
            let t = e0.sub(a).cross(d2) / den;
            let u = e0.sub(a).cross(d1) / den;
            if (0.0..=1.0).contains(&t) && (0.0..=1.0).contains(&u) {
                return 0.0;
            }
        }
        best = best.min(pt_seg(a, e0, e1)).min(pt_seg(b, e0, e1)).min(pt_seg(e0, a, b));
    }
    best
}

// Does segment a→b touch box b (edges included)?''')
open(p,'w').write(s)
print('ok')

