#!/usr/bin/env python3
# mates and seats
import random
random.seed(41)
out = []
sides = ['left', 'right', 'top', 'bottom']
opp = {'left': 'right', 'right': 'left', 'top': 'bottom', 'bottom': 'top'}
for t in range(40):
    w1, h1 = random.choice([(40, 20), (30, 30), (50, 10)])
    w2, h2 = random.choice([(20, 10), (10, 30), (30, 20)])
    s1 = random.choice(sides)
    src = '{ layout: drawing; }\n|rect#a| { width: %d; height: %d; }\n|rect#b| { width: %d; height: %d; translate: %d %d; }\n' % (w1, h1, w2, h2, random.choice([0, 30, -30]), random.choice([0, 30]))
    kind = random.choice(['mate', 'mategap', 'concentric', 'seat', 'seatgap'])
    if kind == 'mate':
        src += 'b:%s || a:%s\n' % (opp[s1], s1)
    elif kind == 'mategap':
        src += 'b:%s || a:%s { gap: %d; }\n' % (opp[s1], s1, random.choice([2, 5, -3]))
    elif kind == 'concentric':
        src += 'b || a\n'
    elif kind == 'seat':
        src += '|datum#d| "A"\nd || a:%s\n' % s1
    elif kind == 'seatgap':
        src += '|surface-finish#sf| "Ra 1.6" { symbol: machined; }\nsf || a:%s { gap: 4; translate: %d 0; }\n' % (s1, random.choice([0, 5]))
    if random.random() < 0.6:
        src += 'a:left (-) b:right { side: bottom; }\n'
    if random.random() < 0.4:
        src += 'a:top (-) b:bottom { side: right; }\n'
    out.append(src)
open('/tmp/annot/v/m6.lini', 'w').write('\n----\n'.join(out))
print(len(out))

