pub fn fmt_val(v: f64) -> String {
    let r = (v.abs() * 100.0 + 0.5 + 1e-9).floor() / 100.0;
    let r = if v < 0.0 { -r } else { r };
    let mut s = format!("{:.2}", r);
    while s.contains('.') && s.ends_with('0') {
        s.pop();
    }
    if s.ends_with('.') {
        s.pop();
    }
    if s == "-0" {
        s = "0".into();
    }
    s
}

